('5ea34027-239f-5419-9568-cac5a98de934', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Pelrêça daneyan a li ser înternetê bêyî paşvegirtinê jî her tim ewle ye.', 'Rast', 'Şaş', '-', '-', 'B', 'Servera dûr jî dikare xera bibe an bê hackkirin; paşvegirtin şertê ewlehiyê ye.', 'Servera dûr jî dikare xera bibe an bê hackkirin; paşvegirtin şertê ewlehiyê ye.', 'Uzak sunucu da bozulabilir ya da ele geçirilebilir; yedekleme güvenliğin şartıdır.', 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0018
