('8a951aab-2cae-5428-8709-04579509ecdc', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Kodên çavkaniyê yên vekirî tenê ji aliyê şirketan ve tên nivîsandin.', 'Rast', 'Şaş', '-', '-', 'B', 'Kodê vekirî ji aliyê kes, komele û şirketan ve bi hev re tê pêşxistin.', 'Kodê vekirî ji aliyê kes, komele û şirketan ve bi hev re tê pêşxistin.', 'Açık kaynak kod; kişiler, topluluklar ve şirketler tarafından birlikte geliştirilir.', 4, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0020
('e2de5c22-ab3b-515b-9690-2e76393e84e9', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Bikaranîna heman şîfreyê ji bo hemû hesaban xetereyê zêde dike.', 'Rast', 'Şaş', '-', '-', 'A', 'Heke yek xizmet bête hackkirin, hemû hesabên bi heman şîfreyê vedibin.', 'Heke yek xizmet bête hackkirin, hemû hesabên bi heman şîfreyê vedibin.', 'Bir servis ele geçirilirse aynı parolayı kullanan tüm hesaplar açılır.', 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0021
