('7a18ba38-7256-56cf-97f1-c7e205a1a6d4', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Klavye ji bo têketina nivîsê tê bikaranîn.', 'Rast', 'Şaş', '-', '-', 'A', 'Klavye tîp û fermanan digihîne komputerê.', 'Klavye tîp û fermanan digihîne komputerê.', 'Klavye, harfleri ve komutları bilgisayara iletir.', 1, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0023
