('684ababb-79c4-5b45-9c7a-8eaee08ff224', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Şîfrekirin daneyê bêyî mifteya rast dîsa xwendinbar dihêle.', 'Rast', 'Şaş', '-', '-', 'B', 'Armanca şîfrekirinê tam ev e: bêyî mifteyê nivîs ne xwendinbar be.', 'Armanca şîfrekirinê tam ev e: bêyî mifteyê nivîs ne xwendinbar be.', 'Şifrelemenin amacı tam da budur: anahtar olmadan metin okunamaz olsun.', 5, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0026
('a3e9ffc1-a8cb-5ba4-9958-e2b9491316d1', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Nûvekirinên nermalavê gelek caran valahiyên ewlehiyê digirin.', 'Rast', 'Şaş', '-', '-', 'A', 'Nûvekirin çewtiyên naskirî yên ku dikarin bên bikaranîn sererast dike.', 'Nûvekirin çewtiyên naskirî yên ku dikarin bên bikaranîn sererast dike.', 'Güncellemeler, sömürülebilir bilinen açıkları kapatır.', 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0027
('e404770e-4a58-54da-942e-56ff4899c418', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Wêneyek bi çareseriya bilind her tim cihê kêmtir digire.', 'Rast', 'Şaş', '-', '-', 'B', 'Bêtir pîksel bêtir dane ye; bi giştî cih zêde dibe, ne kêm.', 'Bêtir pîksel bêtir dane ye; bi giştî cih zêde dibe, ne kêm.', 'Daha çok piksel daha çok veridir; yer genelde artar, azalmaz.', 4, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0028
