('bb2adea3-385b-5114-99b9-552122680c96', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Wêneyên ku model çêdikin, dîmenên rastîn ên kamerayê ne.', 'Rast', 'Şaş', '-', '-', 'B', 'Model wêneyan ji nimûneyên xwe derdixe; ew ne dîmenek e ku kamerayê girtiye. Loma wêneyên wisa dikarin tiştên ku qet çênebûne nîşan bidin.', 'Model wêneyan ji nimûneyên xwe derdixe; ew ne dîmenek e ku kamerayê girtiye. Loma wêneyên wisa dikarin tiştên ku qet çênebûne nîşan bidin.', 'Model, görüntüleri kendi örneklerinden üretir; bu, kameranın çektiği bir sahne değildir. Bu yüzden böyle görüntüler hiç olmamış şeyleri gösterebilir.', 4, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0048
