('ea69d650-bd4a-53df-ae81-029255a0c24a', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Di bernamesaziyê de kîjan hêman çend fermanan di bin navekî de kom dike û paşê gelek caran tê bikaranîn?', 'Guhêrbar', 'Şirove', 'Fonksiyon', 'Koda çavkaniyê', 'C', 'Fonksiyon carekê tê nivîsandin û paşê gelek caran tê bikaranîn; ev yek kodê kurt dike û dubarekirinê kêm dike.', 'Fonksiyon carekê tê nivîsandin û paşê gelek caran tê bikaranîn; ev yek kodê kurt dike û dubarekirinê kêm dike.', 'Fonksiyon bir kez yazılır, sonra defalarca kullanılır; bu, kodu kısaltır ve tekrarı azaltır.', 2, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0060
