('c74bb8a5-e244-5c89-873d-fbaec2b4e440', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Çima di projeyeke nermalavê de pirtûkxaneyeke amade tê bikaranîn?', 'Ji ber ku pirtûkxane hemû çewtiyên bernameyê bi xwe rast dikin', 'Ji ber ku pirtûkxane kodeke ceribandî pêşkêş dike', 'Ji ber ku bêyî pirtûkxaneyê tu bername naxebite', 'Ji ber ku pirtûkxane cihê dîskê kêm dikin', 'B', 'Pirtûkxane kodeke amade û ceribandî pêşkêş dike; ne hewce ye heman kar ji nû ve bê nivîsandin.', 'Pirtûkxane kodeke amade û ceribandî pêşkêş dike; ne hewce ye heman kar ji nû ve bê nivîsandin.', 'Kütüphane hazır ve test edilmiş kod sunar; aynı işi yeniden yazmaya gerek kalmaz.', 5, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0065
('e9c37181-1451-5b29-8ee8-42b6cd988e8a', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Çewtiyeke tîpê ya piçûk jî dikare bernameyekê ji xebatê bixe.', 'Rast', 'Şaş', '-', '-', 'A', 'Berhevkar rêzimana kodê bi awayekî hûr dipîve; tîpeke kêm an zêde têra sekinandina bernameyê dike.', 'Berhevkar rêzimana kodê bi awayekî hûr dipîve; tîpeke kêm an zêde têra sekinandina bernameyê dike.', 'Derleyici kodun dilbilgisini ince ince denetler; eksik ya da fazla tek bir harf bile programı durdurmaya yeter.', 2, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0066
('ec20051f-f741-5acc-bd7f-7288bef1da44', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Şiroveyên di nav kodê de ji aliyê komputerê ve nayên meşandin.', 'Rast', 'Şaş', '-', '-', 'A', 'Şirove ji bo mirovan tên nivîsandin; berhevkar wan derbas dike û tenê fermanan werdigerîne.', 'Şirove ji bo mirovan tên nivîsandin; berhevkar wan derbas dike û tenê fermanan werdigerîne.', 'Yorumlar insanlar için yazılır; derleyici onları atlar ve yalnızca komutları çevirir.', 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0067
('3dec9fcf-085a-5d54-8c09-70f2744e1eb3', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Her zimanê bernamesaziyê ji bo her karî bi heman awayî guncaw e.', 'Rast', 'Şaş', '-', '-', 'B', 'Hêza her zimanî di warekî de ye; ziman li gorî pêwîstiya karî tê hilbijartin.', 'Hêza her zimanî di warekî de ye; ziman li gorî pêwîstiya karî tê hilbijartin.', 'Her dilin gücü ayrı bir alandadır; dil, işin gereğine göre seçilir.', 4, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0068
('e38b3299-6a16-5108-9095-b14925a19839', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Heke hemû ceribandin bi ser bikevin, êdî di kodê de tu çewtî namîne.', 'Rast', 'Şaş', '-', '-', 'B', 'Ceribandin tenê rewşên ku hatine nivîsandin dipîvin; rewşa ku nehatiye ceribandin dikare çewtiyekê veşêre.', 'Ceribandin tenê rewşên ku hatine nivîsandin dipîvin; rewşa ku nehatiye ceribandin dikare çewtiyekê veşêre.', 'Testler yalnızca yazılmış durumları ölçer; denenmemiş bir durum bir hatayı gizleyebilir.', 5, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0069
('27a73342-e678-5139-9392-30b4cfd8928a', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Deng bi gelemperî bi kîjan cureyê dosyayê tê tomarkirin?', 'HTML5', 'JPG', 'MP3', 'PDF', 'C', 'MP3 ji bo deng tê bikaranîn, PDF ji bo nivîsê ye. Bi Kurmancî "deng" tê wateya "ses".', 'MP3 ji bo deng tê bikaranîn, PDF ji bo nivîsê ye. Bi Kurmancî "deng" tê wateya "ses".', 'MP3 ses için kullanılır, PDF ise yazı içindir. Kurmancîde "deng" "ses" demektir.', 1, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0070
('1baad128-f388-5005-ab2b-7ccc78980fef', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Mezinahiya dosyayekê bi çi tê pîvandin?', 'bi metre û kîlometre', 'bi saet û deqîqe', 'bi kîlogram û ton', 'bi bayt û megabayt', 'D', 'Mezinahiya daneyan bi bayt û megabaytê tê pîvandin; metre ji bo dirêjahiyê ye.', 'Mezinahiya daneyan bi bayt û megabaytê tê pîvandin; metre ji bo dirêjahiyê ye.', 'Veri boyutu bayt ve megabaytla ölçülür; metre ise uzunluk içindir.', 2, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0071
('4f91164e-7849-5cb4-93fa-a578996d64bc', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Ji ya herî biçûk ber bi ya herî mezin ve, rêza rast kîjan e?', 'kîlobayt, bayt, megabayt', 'bayt, kîlobayt, megabayt', 'megabayt, kîlobayt, bayt', 'kîlobayt, megabayt, bayt', 'B', 'Kîlobayt ji baytê mezintir e, megabayt jî ji kîlobaytê mezintir e.', 'Kîlobayt ji baytê mezintir e, megabayt jî ji kîlobaytê mezintir e.', 'Kilobayt bayttan büyüktür, megabayt da kilobayttan büyüktür.', 3, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0072
('22104fe6-8e35-5798-a86a-9ec7f50e96c1', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Bi gelemperî kîjan dosya ji hemûyan bêtir cih digire?', 'Dosyayeke nivîsê ya ku çend rêzên kurt digire nav xwe', 'Wêneyek ji ekranê', 'Dosyayeke dengî ya bi çend deqîqeyan', 'Vîdyoyeke bi dirêjahiya deh deqîqeyan', 'D', 'Vîdyo hem wêne hem deng bi hev re digire nav xwe; ji ber wê ji dosyayên nivîsê, wêneyê û dengê pir mezintir e.', 'Vîdyo hem wêne hem deng bi hev re digire nav xwe; ji ber wê ji dosyayên nivîsê, wêneyê û dengê pir mezintir e.', 'Video hem görüntüyü hem sesi birlikte içerir; bu yüzden yazı, resim ve ses dosyalarından çok daha büyüktür.', 3, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0073
('877b8db4-e6c2-5b9f-95ba-f3c89f0d0c90', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Pergala ku agahiyan birêkûpêk hildigire û lêgerînê hêsan dike bi Kurmancî çi ye?', 'Pelgeh', 'Bilindgo', 'Danegeh', 'Textê tiliyan', 'C', 'Danegeh agahiyan birêkûpêk digire; ji ber wê lêgerîn bilez pêk tê.', 'Danegeh agahiyan birêkûpêk digire; ji ber wê lêgerîn bilez pêk tê.', 'Danegeh (veritabanı) bilgileri düzenli tutar; bu yüzden arama hızlı olur.', 2, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0074
('1179954d-ffac-5b18-a615-450dcdf482cf', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Heke paşgirê navê dosyayekê ji .txt bo .mp3 were guhertin, naverok jî dibe deng.', 'Rast', 'Şaş', '-', '-', 'B', 'Paşgir tenê beşek ji nav e; naverok wek xwe dimîne û dosya venabe.', 'Paşgir tenê beşek ji nav e; naverok wek xwe dimîne û dosya venabe.', 'Uzantı yalnızca adın bir parçasıdır; içerik aynı kalır ve dosya açılmaz.', 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0076
('9461357d-9b49-586c-bfb7-2b1b0ad06581', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Dosyayeke PDF li ser amûrên cuda bi heman awayî xuya dike.', 'Rast', 'Şaş', '-', '-', 'A', 'PDF dîmenê rûpelê digire nav xwe; ji ber wê li ser her amûrê naguhere.', 'PDF dîmenê rûpelê digire nav xwe; ji ber wê li ser her amûrê naguhere.', 'PDF sayfanın görünümünü içinde taşır; bu yüzden her cihazda değişmez.', 2, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0077
('cdd71075-11c5-5389-a45e-51d4abd4fee4', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Wêneyên ku bi telefonê tên kişandin dikarin agahiya cihê kişandinê jî di nav xwe de bigirin.', 'Rast', 'Şaş', '-', '-', 'A', 'Telefon bi gelemperî cih û demê bi wêneyê re tomar dike; heke wêne bê parvekirin, ev agahî jî pê re diçe.', 'Telefon bi gelemperî cih û demê bi wêneyê re tomar dike; heke wêne bê parvekirin, ev agahî jî pê re diçe.', 'Telefon genellikle yeri ve zamanı fotoğrafla birlikte kaydeder; fotoğraf paylaşılırsa bu bilgi de onunla gider.', 4, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0078
('b71fbac1-3167-58da-b8c3-4afc60b35487', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Her awayê kêmkirina mezinahiya dosyayan bêyî windakirina agahiyan dixebite.', 'Rast', 'Şaş', '-', '-', 'B', 'Hin awa hin agahiyan davêjin da ku dosya bêtir biçûk bibe; ji ber wê wêne ne wek berê xuya dike.', 'Hin awa hin agahiyan davêjin da ku dosya bêtir biçûk bibe; ji ber wê wêne ne wek berê xuya dike.', 'Bazı yöntemler dosya daha da küçülsün diye bir kısım bilgiyi atar; bu yüzden resim eskisi gibi görünmez.', 5, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0079
('140d55b7-5a83-5f67-9f2f-04b584527549', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Bernameya ku pê rûpelên malperan têne vekirin bi Kurmancî çi ye?', 'Motora lêgerînê', 'Pergala xebitandinê', 'Bernameya e-nameyê', 'Geroker', 'D', 'Geroker rûpelên malperan tîne ser ekranê; motora lêgerînê tenê li wan digere, pergala xebitandinê jî amûrê bi rê ve dibe.', 'Geroker rûpelên malperan tîne ser ekranê; motora lêgerînê tenê li wan digere, pergala xebitandinê jî amûrê bi rê ve dibe.', 'Tarayıcı, web sayfalarını ekrana getirir; arama motoru onları yalnızca arar, işletim sistemi ise cihazı yönetir.', 1, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0080
('14cfd815-dfff-5aae-a582-84f77aaee069', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Peyva Kurmancî "lêgerîn" bi Tirkî çi tê gotin?', 'yazma', 'arama', 'silme', 'kaydetme', 'B', 'Lêgerîn tê wateya ku mirov li tiştekî bigere; motora lêgerînê jî ji bo me li ser înternetê digere.', 'Lêgerîn tê wateya ku mirov li tiştekî bigere; motora lêgerînê jî ji bo me li ser înternetê digere.', 'Lêgerîn, bir şeyi aramak demektir; arama motoru da bizim için internette arar.', 2, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0081
('57ea93e9-96c8-5f6e-9a7f-979cc5ef3415', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Encamên yekem ên motora lêgerînê her tim çavkaniyên herî pêbawer in.', 'Rast', 'Şaş', '-', '-', 'B', 'Hin encam reklam in, hin jî bi teknîkên taybet tên bilindkirin; ji ber wê divê mirov çavkaniyê binirxîne.', 'Hin encam reklam in, hin jî bi teknîkên taybet tên bilindkirin; ji ber wê divê mirov çavkaniyê binirxîne.', 'Bazı sonuçlar reklamdır, bazıları özel tekniklerle üste çıkarılır; bu yüzden kaynağı değerlendirmek gerekir.', 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0082
('b07b4beb-942b-5b87-8e3c-f4df3a5e1bec', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'E-nameyek ji kesekî nenas bi pêvekekê re hat. Tevgera herî ewle kîjan e?', 'Pêvekê veke û bala xwe bide naverokê', 'Pêvekê veneke û e-nameyê jê bibe', 'E-nameyê ji hevalên xwe re bişîne ku ew jî bibînin', 'Bersivê bide û navnîşana xwe ya malê bişîne', 'B', 'Pêvekên ku ji kesên nenas tên, gelek caran nermalava zirardar hildigirin; venekirin rêya herî ewle ye.', 'Pêvekên ku ji kesên nenas tên, gelek caran nermalava zirardar hildigirin; venekirin rêya herî ewle ye.', 'Tanımadığın kişilerden gelen ekler çoğu zaman zararlı yazılım taşır; açmamak en güvenli yoldur.', 3, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0083
('c77fa70b-b55e-517f-8d80-bce0dd0d9dc1', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Mîhengên malbatî yên li ser amûrê dikarin naveroka neguncaw ji zarokan re sînordar bikin.', 'Rast', 'Şaş', '-', '-', 'A', 'Bi van mîhengan malbat dikare naverok û dema bikaranînê sînor bike; lê ew nabe şûna axaftina bi zarokê re.', 'Bi van mîhengan malbat dikare naverok û dema bikaranînê sînor bike; lê ew nabe şûna axaftina bi zarokê re.', 'Bu ayarlarla aile, içeriği ve kullanım süresini sınırlayabilir; ama bu, çocukla konuşmanın yerini tutmaz.', 2, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0084
('6f287e0b-b1cc-58b7-83cc-be9e25648976', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Dema tu li malperekê digerî, "cookie" çi dike?', 'Girêdana înternetê bileztir û bêqablo dike', 'Şîfreyên te yên hesaban diguherîne û nû dike', 'Hemû reklaman ji rûpelên malperan radike û paqij dike', 'Agahiyên gera te li ser amûrê tomar dike', 'D', 'Cookie perçeyeke piçûk a daneyan e ku malper li ser amûra te dihêle, da ku cara din te nas bike.', 'Cookie perçeyeke piçûk a daneyan e ku malper li ser amûra te dihêle, da ku cara din te nas bike.', 'Çerez, sitenin cihazında bıraktığı küçük bir veri parçasıdır; sonraki gelişinde seni tanımasını sağlar.', 4, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0085
('92e1cfb6-2fb0-589c-b21f-dc5e92c7ffee', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Wêne û nivîsên ku tu li ser înternetê belav dikî, piştî jêbirinê jî dikarin li cihên din bimînin.', 'Rast', 'Şaş', '-', '-', 'A', 'Kesên din dikarin kopiyan hilînin an server wan tomar dike; şopa dîjîtal bi hêsanî nayê jêbirin.', 'Kesên din dikarin kopiyan hilînin an server wan tomar dike; şopa dîjîtal bi hêsanî nayê jêbirin.', 'Başkaları kopyasını alabilir ya da sunucu kaydını tutar; dijital ayak izi kolayca silinmez.', 4, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0086
('474b5795-e11b-5271-909c-e52e4c4beee2', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Berî kirînê li ser înternetê, divê mirov pêşî li çi binêre?', 'Bihayê herî erzan û dema gihandinê', 'Hejmara reklamên li ser rûpela sereke ya dikanê', 'Rengê rûpelê û mezinahiya wêneyên hilberê', 'Ewlehiya girêdanê û navûdengê dikanê', 'D', 'Bihayê erzan bi tenê nabe pîvana ewlehiyê; girêdaneke şîfrekirî û dikaneke bi navûdeng du pîvanên sereke ne.', 'Bihayê erzan bi tenê nabe pîvana ewlehiyê; girêdaneke şîfrekirî û dikaneke bi navûdeng du pîvanên sereke ne.', 'Ucuz fiyat tek başına güvenlik ölçütü olmaz; şifreli bir bağlantı ve itibarı bilinen bir mağaza iki temel ölçüttür.', 5, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0087
('1a08c750-8c26-58db-a03f-627f4a545d0d', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Wêneyê ku bi nûçeyekê re tê belavkirin, bi tena serê xwe îsbat dike ku bûyer wisa qewimiye.', 'Rast', 'Şaş', '-', '-', 'B', 'Wêne dikare kevn be an ji bûyereke din be; ji bo piştrastkirinê divê mirov li çavkanî û dîroka wêneyê binêre.', 'Wêne dikare kevn be an ji bûyereke din be; ji bo piştrastkirinê divê mirov li çavkanî û dîroka wêneyê binêre.', 'Fotoğraf eski olabilir ya da başka bir olaya ait olabilir; doğrulamak için kaynağa ve fotoğrafın tarihine bakmak gerekir.', 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0088
('dd58fddd-4a08-5f01-b0f6-d67842525d1b', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Kîjan mîheng diyar dikin ka kî dikare agahiyên te yên hesabê bibîne?', 'Mîhengên dengê amûrê', 'Mîhengên nepenîtiyê', 'Mîhengên zimên û herêmê', 'Mîhengên ronahiya ekranê', 'B', 'Bi mîhengên nepenîtiyê tê diyarkirin ka kî dikare profîl, wêne û agahiyên hesabê bibîne.', 'Bi mîhengên nepenîtiyê tê diyarkirin ka kî dikare profîl, wêne û agahiyên hesabê bibîne.', 'Gizlilik ayarlarıyla, profili, fotoğrafları ve hesap bilgilerini kimin görebileceği belirlenir.', 3, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_0089
('28a73a6e-295e-5bbf-a83b-eff8ff223706', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Panelên li ser banan elektrîkê ji kîjan çavkaniyê çêdikin?', 'Ji bayê ku li deştan tê', 'Ji germahiya ava kûr', 'Ji ronahiya tavê', 'Ji tevgera nav erdê', 'C', 'Panel ronahiya tavê digirin û wê dikin elektrîk; ji ber wê bi şev enerjî nayê hilberandin.', 'Panel ronahiya tavê digirin û wê dikin elektrîk; ji ber wê bi şev enerjî nayê hilberandin.', 'Paneller güneş ışığını tutup elektriğe çevirir; bu yüzden geceleyin enerji üretilmez.', 1, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_2001
('efd58370-8fff-55cb-ac09-929b0fb6ef86', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Bendav bi herikîna avê elektrîkê çêdike.', 'Rast', 'Şaş', '-', '-', 'A', 'Ava ku ji jor dadikeve çerxan dizivirîne; ev zivirîn dibe elektrîk.', 'Ava ku ji jor dadikeve çerxan dizivirîne; ev zivirîn dibe elektrîk.', 'Yukarıdan inen su çarkları döndürür; bu dönüş elektriğe dönüşür.', 2, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_2002
('6be6bdf8-8b0a-500f-8821-6b1b8b256450', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Ji van çavkaniyan kîjan piştî bikaranînê ji nû ve çênabe?', 'Komira ku ji bin erdê tê derxistin', 'Bayê ku li ser deştên fireh diherike', 'Ava çeman û robaran', 'Ronahiya tavê ya rojane', 'A', 'Komir ji nebatên ku bi sedan mîlyon sal berê di bin axê de man pêk hatiye; ba û tav xwe her roj nû dikin, lê komir çavkaniyeke sînordar e.', 'Komir ji nebatên ku bi sedan mîlyon sal berê di bin axê de man pêk hatiye; ba û tav xwe her roj nû dikin, lê komir çavkaniyeke sînordar e.', 'Kömür, yüz milyonlarca yıl önce toprak altında kalan bitkilerden oluşmuştur; rüzgâr ve güneş her gün kendini yeniler, ama kömür sınırlı bir kaynaktır.', 3, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_2003
('55ca3d82-ff51-5e6e-989a-87ed1e36229b', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Trimbêlên elektrîkî li şûna benzînê bi çi dixebitin?', 'Bi komira şewitî', 'Bi ava germ a motorê', 'Bi bataryaya hundirîn', 'Bi bayê ku li ser rê diherike', 'C', 'Batarya bi elektrîkê tê barkirin û motorê dixebitîne; ji ber wê ji van trimbêlan dûman dernakeve.', 'Batarya bi elektrîkê tê barkirin û motorê dixebitîne; ji ber wê ji van trimbêlan dûman dernakeve.', 'Batarya elektrikle doldurulur ve motoru çalıştırır; bu yüzden bu arabalardan duman çıkmaz.', 2, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_2004
('35d6054e-965e-5360-a19d-e81f8d95bef4', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Balafir li bilindahiyên mezin difirin, ji ber ku hewaya tenik pêşî li wan kêmtir digire.', 'Rast', 'Şaş', '-', '-', 'A', 'Li jor hewa kêmtir e; balafir bi heman sotemeniyê rêyeke dirêjtir dibire.', 'Li jor hewa kêmtir e; balafir bi heman sotemeniyê rêyeke dirêjtir dibire.', 'Yukarıda hava daha azdır; uçak aynı yakıtla daha uzun yol alır.', 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_2005
('74eae4a8-7462-5082-8b24-4f565f1cd399', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Çima avdana bi dilopan ji ya bi lehiyê kêmtir avê xerc dike?', 'Ji ber ku av di boriyan de sartir dibe û kêm dibe', 'Ji ber ku av rasterast digihîje kokan', 'Ji ber ku dilop ji lehiyê giran in', 'Ji ber ku zeviyên biçûk kêmtir av dixwazin', 'B', 'Bi vê rêbazê av li ber koka nebatê tê rijandin; av li ser axê belav nabe û kêmtir winda dibe.', 'Bi vê rêbazê av li ber koka nebatê tê rijandin; av li ser axê belav nabe û kêmtir winda dibe.', 'Bu yöntemde su bitkinin kökünün dibine dökülür; toprak yüzeyine yayılmaz ve daha azı kaybolur.', 4, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_2006
('3cb57f1b-e3e9-52c9-bf6a-79a5e7baa583', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Xwarina ku di cihekî sar de tê parastin qet xera nabe.', 'Rast', 'Şaş', '-', '-', 'B', 'Sarî xerabûnê hêdî dike lê bi tevahî ranawestîne; her xwarinê demeke sînordar heye.', 'Sarî xerabûnê hêdî dike lê bi tevahî ranawestîne; her xwarinê demeke sînordar heye.', 'Soğuk bozulmayı yavaşlatır ama tümüyle durdurmaz; her yiyeceğin sınırlı bir süresi vardır.', 2, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_2007
('2dc11481-076e-5aa7-b9fc-8589932d4f94', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Çima çêkirina dermanekî nû bi salan didome?', 'Ji ber ku divê navê wî li her welatekî cuda were qeydkirin û parastin', 'Ji ber ku derman tenê di demsala payizê de tên çêkirin', 'Ji ber ku her derman ji sed pêkhateyên cuda pêk tê', 'Ji ber ku divê ewlehiya wî li ser gelek kesan bê ceribandin', 'D', 'Berî ku derman bigihîje dermanxaneyê, di çend qonaxan de li ser komên mezin tê ceribandin; ev qonax dem dixwazin.', 'Berî ku derman bigihîje dermanxaneyê, di çend qonaxan de li ser komên mezin tê ceribandin; ev qonax dem dixwazin.', 'İlaç eczaneye ulaşmadan önce birkaç aşamada büyük gruplar üzerinde denenir; bu aşamalar zaman ister.', 5, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_2009
('ed3d637b-3410-5776-bbea-143513f5a637', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Peykên li derdora Erdê bi giranî ji bo çi tên bikaranîn?', 'Ji bo veguhastina sînyalan û wêneyan', 'Ji bo hilanîna ava vexwarinê', 'Ji bo hilberandina komirê li jor', 'Ji bo hêdîkirina zivirîna Erdê li dora tavê', 'A', 'Peyk sînyalê ji stasyoneke erdî digire û ji herêmeke fireh re dişîne; ji ber wê weşan digihîje cihên dûr.', 'Peyk sînyalê ji stasyoneke erdî digire û ji herêmeke fireh re dişîne; ji ber wê weşan digihîje cihên dûr.', 'Uydu, sinyali bir yer istasyonundan alır ve geniş bir bölgeye yollar; bu yüzden yayın uzak yerlere ulaşır.', 2, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_2010
('b01408ae-cc48-5c21-9f98-ee629c751b79', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Li stasyona fezayê hêza kişandina Erdê bi tevahî winda dibe, loma astronot li hewayê diherikin.', 'Rast', 'Şaş', '-', '-', 'B', 'Stasyon bi lez li derdora Erdê dikeve; ji ber vê ketina bêdawî wisa xuya dike ku giranî nemaye, lê hêz hîn jî heye.', 'Stasyon bi lez li derdora Erdê dikeve; ji ber vê ketina bêdawî wisa xuya dike ku giranî nemaye, lê hêz hîn jî heye.', 'İstasyon hızla Dünya çevresinde düşer; bu bitmeyen düşüş yüzünden ağırlık kalmamış gibi görünür, ama kuvvet hâlâ vardır.', 4, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_2011
('85745747-77d9-5c72-8377-6b341a70b915', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Av di pîvana Celsius de li kîjan pileyê dikele?', 'Li pêncî pileyan', 'Li bîst pileyan', 'Li sed pileyan', 'Li dused pileyan', 'C', 'Di vê pîvanê de av li sifir pileyan dicemide; ji cemidînê heta kelînê sed pile hene.', 'Di vê pîvanê de av li sifir pileyan dicemide; ji cemidînê heta kelînê sed pile hene.', 'Bu ölçekte su sıfır derecede donar; donmadan kaynamaya kadar yüz derece vardır.', 1, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_2012
('a2af74aa-952a-5ec8-b3c9-4ff62edeed39', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Yekîneya "wat" di jiyana rojane de çi dide zanîn?', 'Hêza ku amûrek xerc dike', 'Giraniya amûrê li ser mêzînê', 'Dirêjahiya qabloya amûrê', 'Dema ku amûr dixebite', 'A', 'Çiqas wat zêde be, amûr ewqas zûtir elektrîkê dixwe; ji ber wê ampûlên kêm wat kêmtir xerc dikin.', 'Çiqas wat zêde be, amûr ewqas zûtir elektrîkê dixwe; ji ber wê ampûlên kêm wat kêmtir xerc dikin.', 'Watt ne kadar yüksekse cihaz elektriği o kadar hızlı tüketir; bu yüzden düşük watlı ampuller daha az harcar.', 3, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_2013
('8e7cda6a-8ec8-561a-b62d-f7b447296032', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Amûreke ku vemirandî ye lê qabloya wê hîn jî girêdayî ye bi tu awayî elektrîkê naxwe.', 'Rast', 'Şaş', '-', '-', 'B', 'Gelek amûr di rewşa razanê de jî hinek elektrîkê dixwin; ji ber wê kişandina qabloyê xercê kêm dike.', 'Gelek amûr di rewşa razanê de jî hinek elektrîkê dixwin; ji ber wê kişandina qabloyê xercê kêm dike.', 'Birçok cihaz bekleme durumunda da biraz elektrik tüketir; bu yüzden kabloyu çekmek harcamayı azaltır.', 5, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_2014
('51593907-4c47-5c73-bad7-10e322cf5a40', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Berî îcada motora buxarê, keştî bi giranî bi çi dimeşiyan?', 'Bi elektrîka bataryayan', 'Bi hêza motorên mazotê', 'Bi tîrêjên tavê yên rasterast', 'Bi hêza bayê û ya mirovan', 'D', 'Keştiyên kevn hêza xwe ji bayê digirtin; dema ba nedihat, mirovan keştî bi destan dimeşandin.', 'Keştiyên kevn hêza xwe ji bayê digirtin; dema ba nedihat, mirovan keştî bi destan dimeşandin.', 'Eski gemiler gücünü rüzgârdan alırdı; rüzgâr esmediğinde gemiyi insanlar elle yürütürdü.', 4, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tek_2015
('049f593c-b28b-568d-a6d7-bbffe0726c78', (select id from categories where name = 'Teknolojî'), 'ku-kmr', '"URL" kurtenivîsa çi ye?', 'Universal Reading Language', 'Uniform Resource Locator', 'Unique Router Link', 'Upper Range Layer', 'B', '"URL" kurtenivîsa "Uniform Resource Locator" e.', '"URL" kurtenivîsa "Uniform Resource Locator" e.', '"URL", "Uniform Resource Locator" ifadesinin kısaltmasıdır.', 2, true, 'multiple_choice', NULL, NULL, 'Source-first verified expansion 2026-08', 'internal:source_first_expansion_2026_08#see=docs/content/verified_external_pool_2026_08/provenance.json', 'approved', 'Kurmancî', 2, now()), -- yerel: sf_tech_0007
('144ac4bd-c64b-57cb-9f8b-cb89a9f68d80', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'URL bi giranî çi diyar dike?', 'Rengê rûpelê', 'Mezinahiya wêneyan', 'Dema xwendinê', 'Navnîşana çavkaniyekê', 'D', 'URL navnîşana çavkaniyekê ye; bi wê navnîşanê çavkanî tê dîtin.', 'URL navnîşana çavkaniyekê ye; bi wê navnîşanê çavkanî tê dîtin.', 'URL bir kaynağın adresidir; o adres sayesinde kaynağa ulaşılır.', 2, true, 'multiple_choice', NULL, NULL, 'Source-first verified expansion 2026-08', 'internal:source_first_expansion_2026_08#see=docs/content/verified_external_pool_2026_08/provenance.json', 'approved', 'Kurmancî', 2, now()), -- yerel: sf_tech_0008
('d6c1e401-37ef-537d-9a77-732c2e98cb09', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Di HTTPê de peyama "200 OK" çi nîşan dide?', 'Girêdan hat birîn', 'Rûpel hat guhertin', 'Daxwaz hat qebûlkirin', 'Navnîşan çewt e', 'C', 'Peyama "200 OK" nîşan dide ku daxwaz hat qebûlkirin û bersiv tê şandin.', 'Peyama "200 OK" nîşan dide ku daxwaz hat qebûlkirin û bersiv tê şandin.', '"200 OK" mesajı, isteğin kabul edildiğini ve yanıtın gönderildiğini gösterir.', 2, true, 'multiple_choice', NULL, NULL, 'Source-first verified expansion 2026-08', 'internal:source_first_expansion_2026_08#see=docs/content/verified_external_pool_2026_08/provenance.json', 'approved', 'Kurmancî', 2, now()), -- yerel: sf_tech_0010
('860992af-40be-5316-840b-9ef8c3bbb69c', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Li gorî rêbernameya nû ya NISTê, tîpên taybet mecbûr in?', 'Na, êdî mecbûr nayên pêşniyarkirin', 'Erê, her dem mecbûr in', 'Tenê ji bo bankan mecbûr in', 'Tenê ji bo e-nameyê mecbûr in', 'A', 'NIST êdî pêşniyar nake ku şîfre bi mecbûrî tîpên taybet û hejmaran bihewîne.', 'NIST êdî pêşniyar nake ku şîfre bi mecbûrî tîpên taybet û hejmaran bihewîne.', 'NIST artık parolaların zorunlu olarak özel karakter ve sayı içermesini önermiyor.', 2, true, 'multiple_choice', NULL, NULL, 'Source-first verified expansion 2026-08', 'internal:source_first_expansion_2026_08#see=docs/content/verified_external_pool_2026_08/provenance.json', 'approved', 'Kurmancî', 2, now()), -- yerel: sf_tech_0012
('115c83dc-1a87-5839-9ad2-f6e1f3c9b0c1', (select id from categories where name = 'Teknolojî'), 'ku-kmr', '"Passphrase" çi ye?', 'Rêzek ji yek tîpê ku gelek caran tê dubarekirin', 'Rêzek ku tenê ji hejmarên li pey hev pêk tê', 'Rêzek ji çend peyvên cuda yên bi hev ve girêdayî', 'Navê bikarhêner ku wek şîfre tê bikaranîn', 'C', 'Passphrase çend peyvên rastîn li hev tîne; hem hêsantir li bîr dimîne hem jî dirêjtir e.', 'Passphrase çend peyvên rastîn li hev tîne; hem hêsantir li bîr dimîne hem jî dirêjtir e.', 'Passphrase birkaç gerçek sözcüğü birleştirir; hem akılda kalıcı hem daha uzundur.', 2, true, 'multiple_choice', NULL, NULL, 'Source-first verified expansion 2026-08', 'internal:source_first_expansion_2026_08#see=docs/content/verified_external_pool_2026_08/provenance.json', 'approved', 'Kurmancî', 2, now()), -- yerel: sf_tech_0013
('625559d2-089c-5db1-8861-1cc95dcac661', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Çima bikaranîna heman şîfreyê li gelek malperan xeternak e?', 'Ji ber ku malper dikarin bi heman şîfreyê hêdîtir bibin', 'Ji ber ku şikandina yek hesabî dikare hesabên din jî bixe xetereyê', 'Ji ber ku şîfreyek li gelek cihan bîranîna wê dijwartir dike', 'Ji ber ku bikaranîna heman şîfreyê trafîka înternetê zêde dike', 'B', 'Ger heman şîfre li malperekê bikeve destan, hemû hesabên bi wê şîfreyê dikevin xetereyê.', 'Ger heman şîfre li malperekê bikeve destan, hemû hesabên bi wê şîfreyê dikevin xetereyê.', 'Aynı parola bir sitede ele geçerse, o parolayı kullanan tüm hesaplar tehlikeye girer.', 2, true, 'multiple_choice', NULL, NULL, 'Source-first verified expansion 2026-08', 'internal:source_first_expansion_2026_08#see=docs/content/verified_external_pool_2026_08/provenance.json', 'approved', 'Kurmancî', 2, now()), -- yerel: sf_tech_0014
('6f3899e1-daf5-557a-8edc-608c3c293ea2', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Yek bayt ji çend bîtan pêk tê?', '4 bît', '6 bît', '8 bît', '16 bît', 'C', 'Baytek ji 8 bîtan pêk tê; ji ber vê yekê baytek dikare 2 bi hêza 8, ango 256 nirxên cuda hilgire. Komên 4, 6 û 16 bîtî wek dirêjahiya baytê ya standard nayên hesibandin.', 'Baytek ji 8 bîtan pêk tê; ji ber vê yekê baytek dikare 2 bi hêza 8, ango 256 nirxên cuda hilgire. Komên 4, 6 û 16 bîtî wek dirêjahiya baytê ya standard nayên hesibandin.', 'Bir bayt 8 bittir; bu yüzden tek bir bayt 2 üzeri 8, yani 256 farklı değer taşıyabilir. 4, 6 ve 16 bitlik gruplar standart bayt uzunluğu sayılmaz.', 2, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=469c8a83f65b2d4d', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0001
('e19e3405-3324-56c0-8e9e-2f1f3164cf93', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Kîjan parçeyê kompîterê fermanên bernameyan bi cih tîne û wek "mejî" tê nasîn?', 'Dîska hişk', 'Karta grafîkê', 'Çavkaniya enerjiyê', 'Pêvajoker (CPU)', 'D', 'Pêvajoker fermanan distîne, wan çareser dike û bi cih tîne. Dîska hişk daneyan hildigire, karta dîmenê wêneyan çêdike, çavkaniya hêzê jî tenê ceryanê peyda dike.', 'Pêvajoker fermanan distîne, wan çareser dike û bi cih tîne. Dîska hişk daneyan hildigire, karta dîmenê wêneyan çêdike, çavkaniya hêzê jî tenê ceryanê peyda dike.', 'İşlemci komutu alır, çözer ve yürütür. Sabit disk veriyi saklar, ekran kartı görüntüyü üretir, güç kaynağı ise yalnızca elektrik sağlar.', 1, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=b49245b8601d5eff', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0002
('c6ed7cb4-d1a9-540c-b7fd-939188181b3e', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Gava ceryana kompîterê tê birîn, naveroka kîjan bîrê winda dibe?', 'Dîska hişk', 'Bîra RAM', 'Bîra SSD', 'Bîra USB', 'B', 'RAM bîreke demkî ye; ji bo parastina naveroka xwe hewceyî ceryana berdewam e. Dîska hişk, SSD û bîra USBê jî heke ceryan were birîn dîsa daneyan diparêzin.', 'RAM bîreke demkî ye; ji bo parastina naveroka xwe hewceyî ceryana berdewam e. Dîska hişk, SSD û bîra USBê jî heke ceryan were birîn dîsa daneyan diparêzin.', 'RAM uçucu bellektir; içeriğini korumak için sürekli elektrik ister. Sabit disk, SSD ve USB bellek elektrik kesilse de veriyi tutmayı sürdürür.', 3, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=02b24b7abe8658e0', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0003
('2cce21ab-63e6-5ab1-b082-2e8dee195b7c', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Kîjan yekîneya daneyê ji megabaytê mezintir e?', 'Kîlobayt', 'Bayt', 'Bît', 'Gîgabayt', 'D', 'Rêzbendî ji biçûk bo mezin wiha ye: bît, bayt, kîlobayt, megabayt, gîgabayt; gîgabayt bi qasî hezar carî ji megabaytê mezintir e.', 'Rêzbendî ji biçûk bo mezin wiha ye: bît, bayt, kîlobayt, megabayt, gîgabayt; gîgabayt bi qasî hezar carî ji megabaytê mezintir e.', 'Sıralama küçükten büyüğe bit, bayt, kilobayt, megabayt, gigabayt biçimindedir; gigabayt megabayttan yaklaşık bin kat büyüktür.', 1, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=61c048eed6dbeac1', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0004
('72130796-1fe9-5eb7-a437-2e5e6fd10f00', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Windows, Linux û macOS mînakên kîjan cureyê nermalavê ne?', 'Gerokên înternetê', 'Bernameyên antîvîrus', 'Pergalên xebitandinê', 'Zimanên bernamesaziyê', 'C', 'Pergala xebitandinê hişkalavê bi rê ve dibe û dihêle bernameyên din bixebitin. Geroka webê, antîvîrus û zimanên bernamesaziyê amûrên cuda ne ku li ser wê dixebitin.', 'Pergala xebitandinê hişkalavê bi rê ve dibe û dihêle bernameyên din bixebitin. Geroka webê, antîvîrus û zimanên bernamesaziyê amûrên cuda ne ku li ser wê dixebitin.', 'İşletim sistemi donanımı yönetir ve öteki programların çalışmasını sağlar. Tarayıcı, antivirüs ve programlama dilleri onun üstünde duran ayrı araçlardır.', 1, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=68bdaf357618eb5c', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0005
('c77b1d86-0639-5a40-bf7a-53f452dd917f', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Hejmara binary 1100 di pergala dehanî de dibe çi?', '6', '10', '14', '12', 'D', 'Nirxên xaneyan ji rastê ber bi çepê ve wiha ne: 1, 2, 4, 8; di hejmara 1100 de xaneyên 8 û 4 tijî ne, kombûna wan dibe 12.', 'Nirxên xaneyan ji rastê ber bi çepê ve wiha ne: 1, 2, 4, 8; di hejmara 1100 de xaneyên 8 û 4 tijî ne, kombûna wan dibe 12.', 'Basamak değerleri sağdan sola 1, 2, 4, 8 diye gider; 1100 sayısında 8 ve 4 basamakları doludur, toplamları 12 eder.', 3, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=94d91fd0bb42c797', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0006
('f0ae3693-ee5e-57d1-99eb-7b72ceda072d', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Taybetiya ku SSDyê ji dîska hişk a klasîk cuda dike çi ye?', 'Parçeyên wê yên livok nîn in', 'Bi dîskên zivirok ên magnetîk dixebite', 'Gava ceryan biqete dane jê tên jêbirin', 'Tenê ji bo bernameyên grafîkê hatiye çêkirin', 'A', 'SSD daneyan di çîpên flashê de dihêle; ne texteyeke zivirok û ne jî milê xwendinê tê de heye, ji ber vê yekê bêdeng e û li hember lêdanan xurt e. Heke ceryan were birîn jî daneyên wê winda nabin.', 'SSD daneyan di çîpên flashê de dihêle; ne texteyeke zivirok û ne jî milê xwendinê tê de heye, ji ber vê yekê bêdeng e û li hember lêdanan xurt e. Heke ceryan were birîn jî daneyên wê winda nabin.', 'SSD veriyi flash çiplerde tutar; dönen tabla ve okuma kolu bulunmaz, bu yüzden sessiz ve darbeye dayanıklıdır. Verisi elektrik kesilse de kalır.', 3, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=cb499f1b208233b6', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0007
('9788fac0-9282-540b-a4d1-474673cae894', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Bi sê bîtan çend nirxên cuda dikarin bên nîşandan?', '3', '6', '7', '8', 'D', 'Ji ber ku her bît du rewş digire, n bît 2 bi hêza n nirxan hildigire; sê bît dibe 2x2x2 = 8. Hejmarên wek 6 û 7 li gorî vê qaîdeya hêzê nayên hesibandin.', 'Ji ber ku her bît du rewş digire, n bît 2 bi hêza n nirxan hildigire; sê bît dibe 2x2x2 = 8. Hejmarên wek 6 û 7 li gorî vê qaîdeya hêzê nayên hesibandin.', 'Her bitin iki durumu olduğu için n bit 2 üzeri n değer taşır; üç bit 2x2x2 = 8 eder. 6 ve 7 gibi sayılar bu üstel kurala uymaz.', 3, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=6771812f431c195d', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0008
('60a15bcb-268d-5372-bd35-2e210cc513e8', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Bîra cache ji bo çi tê bikaranîn?', 'Ji bo gihandina zû ya daneyên pir tên xwestin', 'Ji bo hilanîna domdar a pelên mezin ên vîdyoyê', 'Ji bo zelaltirkirina wêneyê ekranê', 'Ji bo bêtêlkirina girêdana înternetê', 'A', 'Bîra cache bîreke biçûk lê pir bilez e; bi hiştina daneya ku pêvajoker bi lez dixwaze li nêzî xwe, hejmara xwendinê ji bîra sereke ya hêdî kêm dike.', 'Bîra cache bîreke biçûk lê pir bilez e; bi hiştina daneya ku pêvajoker bi lez dixwaze li nêzî xwe, hejmara xwendinê ji bîra sereke ya hêdî kêm dike.', 'Önbellek küçük ama çok hızlı bir bellektir; işlemcinin sık istediği veriyi yakınında tutarak yavaş ana bellekten okuma sayısını azaltır.', 4, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=f6b2193c53fd0217', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0009
('e36aa420-16f3-58c6-adf9-b0a2b67dc8d4', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Pergala hexadecimal ji çend sembolên cuda pêk tê?', '8', '10', '32', '16', 'D', 'Di pergala hexadecimal de hejmarên 0-9 û tîpên A-F hene, bi giştî 16 sembol. Di pergala oktal de 8, di pergala dehanî de jî 10 sembol hene.', 'Di pergala hexadecimal de hejmarên 0-9 û tîpên A-F hene, bi giştî 16 sembol. Di pergala oktal de 8, di pergala dehanî de jî 10 sembol hene.', 'On altılık sistemde 0-9 rakamları ile A-F harfleri, toplam 16 sembol vardır. Sekizlikte 8, onlukta 10 sembol bulunur.', 3, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=bb00bd4c1cb14d5f', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0010
('2235e194-8318-5761-92b4-befc7df29214', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Kîjan amûr agahiyê dixe nav kompîterê?', 'Çaper', 'Klavye', 'Bilindgoh', 'Ekran', 'B', 'Klavye ji bikarhêner daneyan distîne û ji kompîterê re dişîne. Çaper, bilindgoh û ekran jî daneya ku ji kompîterê derdikeve ber bi derve ve didin.', 'Klavye ji bikarhêner daneyan distîne û ji kompîterê re dişîne. Çaper, bilindgoh û ekran jî daneya ku ji kompîterê derdikeve ber bi derve ve didin.', 'Klavye kullanıcıdan veri alıp bilgisayara iletir. Yazıcı, hoparlör ve ekran ise bilgisayardan çıkan veriyi dışarı verir.', 1, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=af7dcd3c1939f46e', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0011
('81687d91-d4c9-50cf-abf2-412e5705f22f', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Hejmara dehanî 13 di pergala binary de çawa tê nivîsandin?', '1011', '1110', '1101', '1001', 'C', 'Hejmara 13 wek 8 + 4 + 1 tê parvekirin; ev jî ji çepê ber bi rastê ve reqemên 1101 dide. Hejmara 1011 hevbera 11, ya 1110 jî hevbera 14an e.', 'Hejmara 13 wek 8 + 4 + 1 tê parvekirin; ev jî ji çepê ber bi rastê ve reqemên 1101 dide. Hejmara 1011 hevbera 11, ya 1110 jî hevbera 14an e.', '13 sayısı 8 + 4 + 1 biçiminde ayrışır; bu da soldan sağa 1101 basamaklarını verir. 1011 sayısı 11''e, 1110 ise 14''e karşılık gelir.', 4, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=325c26532e1023f9', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0012
('1b9e982d-51e3-5cae-aade-9141a754e0f5', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Têgeha "nermalav" çi vedibêje?', 'Bername û fermanên ku li ser kompîterê dixebitin', 'Parçeyên fizîkî yên ku mirov dikare bi dest bigire', 'Kabloyên ku amûran bi hev ve girê didin', 'Enerjiya elektrîkê ya ku kompîter dixwe', 'A', 'Nermalav komek ferman û bernameyan e ku ji reqalavê re dibêje çi bike. Perçeyên ku bi destan tên girtin û kablo wek reqalav tên hesibandin.', 'Nermalav komek ferman û bernameyan e ku ji reqalavê re dibêje çi bike. Perçeyên ku bi destan tên girtin û kablo wek reqalav tên hesibandin.', 'Yazılım, donanıma ne yapacağını söyleyen komut ve program bütünüdür. Elle tutulan parçalar ve kablolar donanım sayılır.', 2, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=950a2c4dadd5a1ab', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0013
('53addfc8-8531-57bd-b7d0-f96d6ff95270', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Kîjan bîr bi giranî tenê ji bo xwendinê ye û naveroka xwe bêyî ceryan diparêze?', 'RAM', 'Cache', 'Bîra virtual', 'ROM', 'D', 'ROM bîreke ku tenê tê xwendin e, dema ceryan were birîn naveroka wê nayê jêbirin û nermalava vebûnê li wir dimîne. RAM û bîra cache demkî ne, bîra virtual jî li ser dîskê tê hiştin.', 'ROM bîreke ku tenê tê xwendin e, dema ceryan were birîn naveroka wê nayê jêbirin û nermalava vebûnê li wir dimîne. RAM û bîra cache demkî ne, bîra virtual jî li ser dîskê tê hiştin.', 'ROM salt okunur bellektir, içeriği elektrik kesilince silinmez ve açılış yazılımı orada durur. RAM ile önbellek uçucudur, sanal bellek ise diskte tutulur.', 3, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=f44b42969b62e0c2', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0014
('cc0ebab3-c8a4-5fbd-b685-e9cbc11106ca', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Yekîneya gigahertz (GHz) di pêvajokeran de çi dipîve?', 'Hejmara çerxên demjimêrê di çirkeyekê de', 'Mezinahiya bîra hilanînê ya li ser dîska hişk', 'Hejmara pelên vekirî', 'Asta germahiya kompîterê', 'A', 'Hertz hejmara çerxan a di çirkeyekê de ye, 1 GHz tê wateya mîlyar çerxan di çirkeyekê de. Hilanîna daneyan bi baytan, germahî jî bi dereceyan tê pîvan.', 'Hertz hejmara çerxan a di çirkeyekê de ye, 1 GHz tê wateya mîlyar çerxan di çirkeyekê de. Hilanîna daneyan bi baytan, germahî jî bi dereceyan tê pîvan.', 'Hertz saniyedeki çevrim sayısıdır, 1 GHz saniyede bir milyar çevrim demektir. Depolama baytla, sıcaklık dereceyle ölçülür.', 3, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=ae9ffa33797ec554', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0015
('9c166f62-2ac2-5a91-954a-fbf5bdb516dc', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Paşgira pelê (wek .txt an .jpg) bi giştî çi diyar dike?', 'Mezinahiya pelê bi bayt, kilobayt an megabaytan', 'Dîroka çêkirina pelê', 'Cureya naverokê û bernameya ku wê vedike', 'Cihê ku pel lê hatiye hilanîn', 'C', 'Paşgir ji pergala xebitandinê re dibêje formata pelê çi ye û bi kîjan bernameyê were vekirin. Mezinahî, dîrok û cih taybetiyên din ên pelê ne, ji hev cuda ne.', 'Paşgir ji pergala xebitandinê re dibêje formata pelê çi ye û bi kîjan bernameyê were vekirin. Mezinahî, dîrok û cih taybetiyên din ên pelê ne, ji hev cuda ne.', 'Uzantı, işletim sistemine dosyanın biçimini ve hangi programla açılacağını söyler. Boyut, tarih ve konum dosyanın ayrı ayrı özellikleridir.', 3, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=bed305f7a859ac45', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0016
('809985cd-f4db-5b64-9474-b50f580c7dd0', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Sedema sereke ya derbasbûna ji pergalên 32-bit bo 64-bit çi bû?', 'Bikaranîna bîreke sereke ya pir mezintir', 'Mezinkirina ekranan', 'Kurtkirina kabloyan', 'Piçûkkirina pelên nivîsê û belgeyên ofîsê', 'A', 'Navnîşankirina 32-bît dikare bi qasî 4 GB bîrê nîşan bide; qada navnîşanê ya 64-bît bi awayekî pratîkî vî sînorî radike. Ev bi ekran, kablo an mezinahiya pelan ve girêdayî nîne.', 'Navnîşankirina 32-bît dikare bi qasî 4 GB bîrê nîşan bide; qada navnîşanê ya 64-bît bi awayekî pratîkî vî sînorî radike. Ev bi ekran, kablo an mezinahiya pelan ve girêdayî nîne.', '32 bitlik adresleme yaklaşık 4 GB belleği gösterebilir; 64 bitlik adres alanı bu sınırı pratikte kaldırır. Ekran, kablo ve dosya boyutuyla ilgisi yoktur.', 4, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=99227b8ccc226230', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0017
('d4121ea8-b720-594d-8ab0-a99b6508eb26', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Dema kompîter vedibe, kîjan nermalav berî pergala xebitandinê dixebite?', 'Geroka înternetê ya standard', 'Bernameya antîvîrus', 'Edîtora nivîsê', 'Firmware (BIOS/UEFI)', 'D', 'Di dema vebûnê de firmwareya li ser karta dayikê reqalavê kontrol dike û pergala xebitandinê li bîrê bar dike. Geroka webê û antîvîrus tenê piştî ku pergal vebe dikevin xebatê.', 'Di dema vebûnê de firmwareya li ser karta dayikê reqalavê kontrol dike û pergala xebitandinê li bîrê bar dike. Geroka webê û antîvîrus tenê piştî ku pergal vebe dikevin xebatê.', 'Açılışta anakart üstündeki ürün yazılımı donanımı sınar ve işletim sistemini belleğe yükler. Tarayıcı ile antivirüs ancak sistem açıldıktan sonra devreye girer.', 4, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=57085557d95bd8e5', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0018
('7563411b-f174-5410-82ba-b3a74cebe9f9', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Nirxa dehanî ya hejmara binary 11111111 çi ye?', '255', '127', '128', '254', 'A', 'Gava hemû heşt bît 1 bin, kombûn dibe 2 bi hêza 8 kêm 1, ango 255; ji ber vê yekê baytek herî zêde nirxa 255an digire. 256 jî hejmara nirxên cuda ye.', 'Gava hemû heşt bît 1 bin, kombûn dibe 2 bi hêza 8 kêm 1, ango 255; ji ber vê yekê baytek herî zêde nirxa 255an digire. 256 jî hejmara nirxên cuda ye.', 'Sekiz basamağın hepsi 1 olduğunda toplam 2 üzeri 8 eksi 1, yani 255 eder; bu yüzden bir bayt en çok 255 değerini tutar. 256 ise farklı değerlerin adedidir.', 4, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=7529423b828a7399', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0019
('5d24e19d-8c4c-5e62-b1a1-c85b5fd9f869', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Erka sereke ya pergala DNSê çi ye?', 'Navên malperan vediguherîne navnîşanên IPê', 'Pelên mezin şîfre dike', 'Leza girêdanê zêde dike', 'E-nameyên nexwestî berî gihîştina qutîkê digire', 'A', 'Mirov navê domainê dinivîsin, kompîter jî bi navnîşana IP diaxivin; DNS di navbera van herduyan de wergerê dike. Şîfrekirin û parzûnkirina spamê erka pergalên din e.', 'Mirov navê domainê dinivîsin, kompîter jî bi navnîşana IP diaxivin; DNS di navbera van herduyan de wergerê dike. Şîfrekirin û parzûnkirina spamê erka pergalên din e.', 'İnsanlar alan adı yazar, bilgisayarlar IP adresiyle konuşur; DNS ikisi arasında çeviri yapar. Şifreleme ve spam süzme başka sistemlerin işidir.', 2, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=38011fc801984a03', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0020
('30b8690c-4699-5658-a7c4-1639d25d2c82', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'HTTPS bi çi awayî ji HTTPê cuda dibe?', 'Rûpel zûtir tên barkirin', 'Rûpel bêyî wêne tên nîşandan', 'Danûstandin bi şîfrekirinê tê parastin', 'Tenê li ser têlefonan dixebite', 'C', 'HTTPS trafîkê bi TLS şîfre dike, kesê di navberê de nikare naverokê bixwîne. Ev bi lez, nîşandana wêneyan an cureyê amûrê ve ne girêdayî ye.', 'HTTPS trafîkê bi TLS şîfre dike, kesê di navberê de nikare naverokê bixwîne. Ev bi lez, nîşandana wêneyan an cureyê amûrê ve ne girêdayî ye.', 'HTTPS trafiği TLS ile şifreler, aradaki biri içeriği okuyamaz. Hızla, görsellerin gösterimiyle ya da cihaz türüyle bir ilgisi yoktur.', 2, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=2bdcd4884af167c6', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0021
('e793a399-1639-512e-bd89-9c504c35d8b7', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Navnîşana IPê di torê de çi diyar dike?', 'Nasnameya hejmarî ya amûrê', 'Cureya gerokê û pergala xebitandinê', 'Leza girêdanê', 'Mezinahiya pelê', 'A', 'Ji bo ku paket bighêjin makîneya rast, ji her amûrekê re navnîşaneke hejmarî tê dayîn. Lez, geroka webê û mezinahiya pelê ji vê navnîşanê serbixwe ne.', 'Ji bo ku paket bighêjin makîneya rast, ji her amûrekê re navnîşaneke hejmarî tê dayîn. Lez, geroka webê û mezinahiya pelê ji vê navnîşanê serbixwe ne.', 'Paketlerin doğru makineye ulaşması için her aygıta sayısal bir adres verilir. Hız, tarayıcı ve dosya boyutu bu adresten bağımsızdır.', 3, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=ccee0659a70f5ce0', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0022
('5a750cf0-40e5-5ebe-bc04-5f6d3461dc8a', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Bluetooth li gorî Wi-Fiyê bi giranî ji bo çi tê tercîhkirin?', 'Ji bo veguhastina daneyan di navbera bajaran de', 'Ji bo belavkirina înternetê li tevahiya avahiyê', 'Ji bo girêdana serverên navneteweyî', 'Ji bo girêdana amûrên nêzîk bi enerjiyeke kêm', 'D', 'Bluetooth di dûrahiyeke kin de bi enerjiyeke kêm dixebite; amûrên wek guhk, klavye û saetê girê dide. Belavkirina înternetê li qadeke fireh erka Wi-Fiyê ye.', 'Bluetooth di dûrahiyeke kin de bi enerjiyeke kêm dixebite; amûrên wek guhk, klavye û saetê girê dide. Belavkirina înternetê li qadeke fireh erka Wi-Fiyê ye.', 'Bluetooth kısa mesafede düşük güçle çalışır; kulaklık, klavye ve saat gibi aygıtları bağlar. Geniş alana internet dağıtmak Wi-Fi''nin işidir.', 2, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=c64d6ae2dad31c71', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0023
('82b74941-cb6e-5f35-a5a3-8c2991db1f5f', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Koda 404 ya HTTPê tê çi wateyê?', 'Çavkanî li ser server nehat dîtin', 'Server zêde bar girtiye', 'Daxwaz bi serkeftî hat temamkirin', 'Bikarhêner xwedî destûr nîne', 'A', 'Koda 404 dibêje ku gihîştin serverê pêk hatiye lê navnîşana xwestî li wir tune ye. Ji bo serkeftinê 200, ji bo pirsgirêkên destûrê jî 401 û 403 tên bikaranîn.', 'Koda 404 dibêje ku gihîştin serverê pêk hatiye lê navnîşana xwestî li wir tune ye. Ji bo serkeftinê 200, ji bo pirsgirêkên destûrê jî 401 û 403 tên bikaranîn.', '404 kodu sunucuya ulaşıldığını ama istenen adresin orada olmadığını bildirir. Başarı için 200, yetki sorunları için 401 ve 403 kullanılır.', 3, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=736d2890fdbb2c0b', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0024
('b06dd1c1-9eca-5b10-aba7-8c554f947041', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Kîjan protokol ji bo şandina e-nameyan tê bikaranîn?', 'IMAP', 'POP3', 'SMTP', 'FTP', 'C', 'SMTP ji bo şandina e-nameyan tê bikaranîn; IMAP û POP3 ji bo xwendina peyamên hatî ji serverê, FTP jî ji bo veguhastina pelan e.', 'SMTP ji bo şandina e-nameyan tê bikaranîn; IMAP û POP3 ji bo xwendina peyamên hatî ji serverê, FTP jî ji bo veguhastina pelan e.', 'SMTP posta göndermeye yarar; IMAP ve POP3 gelen postayı sunucudan okumak, FTP ise dosya aktarmak içindir.', 3, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=ccfe06fe4550d00c', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0025
('fc069fd1-65a8-58f1-aebd-74fc63e7033f', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Çerez (cookie) di gerokê de bi giranî ji bo çi tê bikaranîn?', 'Ji bo bîranîna rewşa bikarhêner', 'Ji bo zêdekirina leza pêvajoker', 'Ji bo şîfrekirina trafîka ku di torê re derbas dibe', 'Ji bo çapkirina rûpelan', 'A', 'Çerez tomareke biçûk e ku malper li ser gerokê dihêle; ji bo ku danişîn vekirî bimîne an tercîh bên parastin tê bikaranîn. Şîfrekirinê TLS li ser xwe digire.', 'Çerez tomareke biçûk e ku malper li ser gerokê dihêle; ji bo ku danişîn vekirî bimîne an tercîh bên parastin tê bikaranîn. Şîfrekirinê TLS li ser xwe digire.', 'Çerez, sitenin tarayıcıya bıraktığı küçük bir kayıttır; oturum açık kalsın ya da tercihler korunsun diye tutulur. Şifrelemeyi TLS üstlenir.', 4, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=ff5fe5e518b4673e', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0026
('cf8ecc8c-73ad-547e-a107-89d9d3629c68', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Erka router (rêker) di tora malê de çi ye?', 'Daneyên amûrên li ser torê bi awayekî domdar hiltîne', 'Ekranê bi înternetê ve girê dide', 'Ji bo bikarhêner şîfreyan çêdike', 'Trafîka navbera tora malê û derve birêve dibe', 'D', 'Rêker ji paketan re dibêje ji kîjan rêyê biçin û tora herêmî bi tora derve ve girê dide. Hilanîna daneyan û çêkirina şîfreyan ne erka wî ye.', 'Rêker ji paketan re dibêje ji kîjan rêyê biçin û tora herêmî bi tora derve ve girê dide. Hilanîna daneyan û çêkirina şîfreyan ne erka wî ye.', 'Yönlendirici paketlere hangi yoldan gideceklerini söyler ve yerel ağı dış ağa bağlar. Veri saklamak ve parola üretmek onun işi değildir.', 3, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=55df842202f5f918', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0027
('dd9d5658-1319-5c65-83f3-25864c02f206', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Cudahiya sereke ya di navbera TCP û UDPyê de çi ye?', 'TCP gihandina rêzdar piştrast dike, UDP nake', 'TCP tenê wêne, UDP tenê nivîs vediguhêze', 'TCP bêtêl e, UDP bi kablo ye', 'TCP şîfre dike, UDP navnîşan diguherîne', 'A', 'TCP kontrol dike ka paket gihîştine an na û rêza wan çi ye, yên wendabûyî ji nû ve dişîne. UDP vê kontrolê nake, ji ber vê yekê bileztir e lê ti garantiya gihîştinê nade.', 'TCP kontrol dike ka paket gihîştine an na û rêza wan çi ye, yên wendabûyî ji nû ve dişîne. UDP vê kontrolê nake, ji ber vê yekê bileztir e lê ti garantiya gihîştinê nade.', 'TCP paketlerin ulaştığını ve sırasını denetler, kaybolanı yeniden gönderir. UDP bu denetimi yapmadığı için daha hızlıdır ama teslim güvencesi vermez.', 4, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=391a4b1feef97fca', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0028
('456dbdc6-2740-5615-bb8b-267bb657532a', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Kîjan ziman avaniya rûpelên webê pênase dike?', 'CSS', 'SQL', 'HTML', 'Python', 'C', 'HTML kevirên avaniyê yên rûpelê, wek sernav, paragraf û girêdanan, ava dike. CSS xuyangê rêk dixe, SQL danegehê pirsyar dike, Python jî zimanekî bi armanca giştî ye.', 'HTML kevirên avaniyê yên rûpelê, wek sernav, paragraf û girêdanan, ava dike. CSS xuyangê rêk dixe, SQL danegehê pirsyar dike, Python jî zimanekî bi armanca giştî ye.', 'HTML sayfanın başlık, paragraf ve bağlantı gibi yapı taşlarını kurar. CSS görünümü düzenler, SQL veritabanı sorgular, Python genel amaçlı bir dildir.', 3, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=1182106f21becd0e', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0029
('1009c705-644b-57f0-8034-46779faac194', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Navnîşaneke IPv4 ji çend bîtan pêk tê?', '32', '8', '16', '128', 'A', 'Navnîşanên IPv4 32 bît in û wek çar komên heştbîtî tên nivîsandin; nirxa her komekê di navbera 0 û 255an de ye. Dirêjahiya 128 bîtî ya navnîşanên IPv6ê ye.', 'Navnîşanên IPv4 32 bît in û wek çar komên heştbîtî tên nivîsandin; nirxa her komekê di navbera 0 û 255an de ye. Dirêjahiya 128 bîtî ya navnîşanên IPv6ê ye.', 'IPv4 adresleri 32 bittir ve dört sekizli sayı olarak yazılır; her sekizli 0 ile 255 arasındadır. 128 bitlik uzunluk IPv6 adreslerine aittir.', 5, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=8232e9e00c58d44f', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0030
('609c0888-79ec-5aa4-a1c2-8cd60d07e06f', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Di navnîşana e-nameyê de sembola @ çi ji hev vediqetîne?', 'Navê bikarhêner û navê domainê', 'Sernav û naveroka nameyê', 'Şîfre û navê bikarhêner', 'Dîrok û demjimêra şandinê', 'A', 'Li çepê navê ku qutîkê nas dike heye, li rastê jî qada ku ew qutîk lê ye; serverê postê bi lêvegerandina van her du perçeyan navnîşanê çareser dike.', 'Li çepê navê ku qutîkê nas dike heye, li rastê jî qada ku ew qutîk lê ye; serverê postê bi lêvegerandina van her du perçeyan navnîşanê çareser dike.', 'Solda kutuyu tanımlayan ad, sağda o kutunun bulunduğu alan vardır; posta sunucusu adresi bu iki parçaya bakarak çözer.', 1, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=ec359898e7b1ded8', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0031
('3cff2784-9dff-5e1c-aa5c-4f3fed0dcc1c', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Gava navnîşanek di qada BCCyê de tê nivîsandin, çi diqewime?', 'Name piştî demekê tê şandin', 'Name bixweber tê şîfrekirin', 'Name du caran tê şandin', 'Wergirên din wê navnîşanê nabînin', 'D', 'BCC qada kopyaya veşartî ye; kesê ku li wir e peyamê distîne lê navnîşana wî ji wergirên din re xuya nake. Navnîşanên di qada CCyê de ji bo hemûyan vekirî ne.', 'BCC qada kopyaya veşartî ye; kesê ku li wir e peyamê distîne lê navnîşana wî ji wergirên din re xuya nake. Navnîşanên di qada CCyê de ji bo hemûyan vekirî ne.', 'BCC gizli kopya alanıdır; oradaki kişi iletiyi alır ama adresi öteki alıcıların listesinde görünmez. CC alanındaki adresler ise herkese açıktır.', 3, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=574cf3bbe91e6666', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0032
('1a8037d5-f60c-5b1f-9824-371127c8c32f', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Li gorî bendika 5 GHz, bendika 2.4 GHz a Wi-Fiyê çi taybetî nîşan dide?', 'Dûrtir digihîje lê hêdîtir e', 'Kêmtir dûr diçe lê zûtir e', 'Tenê bi kabloyê dixebite', 'Tenê ji bo çaperan hatiye çêkirin', 'A', 'Pêla bi frekansa nizm çêtir di dîwaran re derbas dibe û qadeke firehtir vedigire; 5 GHz jî lezeke bilindtir dide lê menzîla wê kurttir e û li ber astengan digire.', 'Pêla bi frekansa nizm çêtir di dîwaran re derbas dibe û qadeke firehtir vedigire; 5 GHz jî lezeke bilindtir dide lê menzîla wê kurttir e û li ber astengan digire.', 'Düşük frekanslı dalga duvarları daha iyi aşar ve geniş alan kaplar; 5 GHz ise daha yüksek hız sunar ama menzili kısadır ve engellere takılır.', 3, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=18eaf32c62d5e9b8', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0033
('7fdede05-666f-5203-94b0-471aa3e6c64b', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Modem di girêdana înternetê de çi dike?', 'Şîfreyan diparêze', 'Pelên bikarhêner li ser dîska xwe ya hundirîn tomar dike', 'Sînyalê ji formekê bo ya din vediguherîne', 'Rûpelan çap dike', 'C', 'Modem sînyala ku ji xeta têlefonê tê vediguherîne daneya hejmarî ku kompîter jê fêm dike, û daneya ji kompîterê tê jî vediguherîne sînyala li gorî xetê. Rêvekirin û hilanîn erka amûrên din e.', 'Modem sînyala ku ji xeta têlefonê tê vediguherîne daneya hejmarî ku kompîter jê fêm dike, û daneya ji kompîterê tê jî vediguherîne sînyala li gorî xetê. Rêvekirin û hilanîn erka amûrên din e.', 'Modem hattan gelen sinyali bilgisayarın anlayacağı sayısal veriye, giden veriyi de hatta uygun sinyale çevirir. Yönlendirme ve depolama başka aygıtların işidir.', 3, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=5e2c6321fbeeae77', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0034
('bfbfe16a-2e21-5509-83f0-108534fae711', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Têgeha "latency" di torê de çi dipîve?', 'Dema ku dane heta bigihîje derbas dike', 'Hejmara amûrên girêdayî', 'Mezinahiya giştî ya pelên hatine daxistin', 'Hejmara malperên vekirî', 'A', 'Latency dem e û bi mîlîsaniyeyan tê pîvan; firehiya bendikê jî mîqdara daneya ku di demeke diyar de dikare bê veguhastin e. Dibe ku li ser xetekê ya yek bilind be, ya din nizm be.', 'Latency dem e û bi mîlîsaniyeyan tê pîvan; firehiya bendikê jî mîqdara daneya ku di demeke diyar de dikare bê veguhastin e. Dibe ku li ser xetekê ya yek bilind be, ya din nizm be.', 'Gecikme bir süredir, milisaniyeyle ölçülür; bant genişliği ise birim zamanda taşınabilen veri miktarıdır. Hattın biri yüksek, öteki düşük olabilir.', 4, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=91bdf0396717be6d', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0035
('8d68de36-6bf7-5024-97df-62b45069b957', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Di modela xerîdar-server de erka serverê çi ye?', 'Ji malperên din re bi domdarî daxwazan dişîne', 'Tenê wêneyan hilberîne', 'Kabloyên torê dirêj dike', 'Daxwazan werdigire û bersivê vedigerîne', 'D', 'Server li bendê dimîne, daxwaza hatî dişixulîne û bersivê vedigerîne; aliyê ku daxwazê dest pê dike xerîdar e. Geroka webê di vê modelê de di rola xerîdar de ye.', 'Server li bendê dimîne, daxwaza hatî dişixulîne û bersivê vedigerîne; aliyê ku daxwazê dest pê dike xerîdar e. Geroka webê di vê modelê de di rola xerîdar de ye.', 'Sunucu bekler, gelen isteği işler ve yanıtı geri gönderir; isteği başlatan taraf istemcidir. Tarayıcı bu modelde istemci konumundadır.', 3, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=d34750399161ea28', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0036
('331d5ca5-e8bf-5e5a-890e-33d11d2c1a3f', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Porta standard a trafîka HTTPSê kîjan e?', '21', '80', '443', '25', 'C', 'HTTPS porta hejmara 443 bikar tîne; 80 ji bo HTTPya bêşîfre, 21 ji bo FTPyê, 25 jî ji bo trafîka SMTPyê ya di navbera serveran de tê veqetandin.', 'HTTPS porta hejmara 443 bikar tîne; 80 ji bo HTTPya bêşîfre, 21 ji bo FTPyê, 25 jî ji bo trafîka SMTPyê ya di navbera serveran de tê veqetandin.', 'HTTPS 443 numaralı portu kullanır; 80 şifresiz HTTP''ye, 21 FTP''ye, 25 ise sunucular arası SMTP trafiğine ayrılmıştır.', 5, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=ce3222c447748c90', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0037
('6c8e5d74-519c-5098-bb5a-5c8457df8026', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Piştrastkirina du gavî ewlehiyê çawa zêde dike?', 'Şîfreyê dirêjtir dike', 'Ji bilî şîfreyê belgeyeke duyem dixwaze', 'Girêdanê zûtir dike', 'E-nameyan bixweber şîfre dike', 'B', 'Heke şîfre bê dizîn jî, ji ber ku li ba êrîşkar delîleke duyem a wek koda ku ji telefonê re tê an mifteya ewlehiyê tune ye, têketin nayê temamkirin.', 'Heke şîfre bê dizîn jî, ji ber ku li ba êrîşkar delîleke duyem a wek koda ku ji telefonê re tê an mifteya ewlehiyê tune ye, têketin nayê temamkirin.', 'Parola çalınsa bile saldırganda telefona gelen kod ya da güvenlik anahtarı gibi ikinci kanıt bulunmaz, giriş bu yüzden tamamlanamaz.', 2, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=bfb1635758f9dee9', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0038
('9c97930f-d34d-5110-a276-74025922bbac', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Êrîşa phishing bi giranî çawa dixebite?', 'Bi şandina daxwazên pir ku serverê qelebalix dikin', 'Bi daxistina bernameyên ku pelan bê destûr diguherînin', 'Bi têketina torê û guherandina şîfreyên bikarhêneran', 'Bi peyamên sexte ku xwe wek çavkaniyên pêbawer nîşan didin', 'D', 'Êrîşkar xwe dixe şiklê dezgeheke naskirî û bikarhêner qaneh dike ku bi destê xwe şîfre an koda xwe bide; hewce nake ku bi awayekî teknîkî pergalê bişkîne.', 'Êrîşkar xwe dixe şiklê dezgeheke naskirî û bikarhêner qaneh dike ku bi destê xwe şîfre an koda xwe bide; hewce nake ku bi awayekî teknîkî pergalê bişkîne.', 'Saldırgan tanıdık bir kurumun kılığına girip kullanıcıyı parolasını ya da kodunu kendi eliyle vermeye ikna eder; teknik bir kırma gerekmez.', 2, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=e26a6064194b5bac', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0039
('520d4239-d2fd-529d-bd27-3ade68c94bb0', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Kîjan taybetî şîfreyekê li hember texmînkirinê xurttir dike?', 'Dirêjahiya zêde û tevliheviya karakteran', 'Bikaranîna paşnavê malbatê', 'Bikaranîna dîroka jidayikbûnê', 'Bikaranîna heman şîfreyê li her malperê û hesabê', 'A', 'Her karaktera ku tê zêdekirin, hejmara îhtîmalên ku divê bên ceribandin çend qatan zêde dike. Agahiyên kesane yên wek paşnav û dîroka jidayikbûnê bi hêsanî tên dîtin û tiştên pêşî ne ku êrîşkar diceribînin.', 'Her karaktera ku tê zêdekirin, hejmara îhtîmalên ku divê bên ceribandin çend qatan zêde dike. Agahiyên kesane yên wek paşnav û dîroka jidayikbûnê bi hêsanî tên dîtin û tiştên pêşî ne ku êrîşkar diceribînin.', 'Eklenen her karakter denenmesi gereken olasılığı katlar. Soyadı ve doğum tarihi gibi kişisel bilgiler kolay bulunur, saldırganın ilk denediği şeydir.', 1, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=11dadddbed7ce1b6', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0040
('8c6efb3c-3b95-59fe-96f1-c9bbc7a37052', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Çima divê kopiyeke ewlehiyê li cihekî fizîkî yê din bê hilanîn?', 'Ji ber ku wisa pel piçûktir dibin', 'Ji ber ku wisa şîfre ne hewce ye', 'Ji ber ku wisa înternet zûtir dibe', 'Ji ber ku agir an dizî nikare her duyan bibe', 'D', 'Eger kopiya ewlehiyê û daneya orîjînal di heman odeyê de bin, agirek, lehiyeke avê an jî diziyek dikare her duyan bi hev re ji holê rake; cihê veqetandî pêşî li vê rîska hevpar digire.', 'Eger kopiya ewlehiyê û daneya orîjînal di heman odeyê de bin, agirek, lehiyeke avê an jî diziyek dikare her duyan bi hev re ji holê rake; cihê veqetandî pêşî li vê rîska hevpar digire.', 'Yedek asıl veriyle aynı odadaysa tek bir yangın, su baskını ya da hırsızlık ikisini birden götürür; ayrı konum bu ortak riski keser.', 3, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=24f808e9de9b568e', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0041
('3ef1bec2-c199-50fc-b06c-55e80fc20dff', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Sedema sereke ya sazkirina nûvekirinên ewlehiyê çi ye?', 'Ji bo girtina qulikên naskirî yên nermalavê', 'Ji bo ku ekran ronîtir û rengên wê zelaltir bibin', 'Ji bo kêmkirina cihê dîskê', 'Ji bo guhertina zimanê pergalê', 'A', 'Nûvekirin qelsiyên hatine ragihandin digire. Piştî ku qelsî hat ragihandin, êrîşkar jî pê dizanin, ji ber vê yekê paşxistina sazkirinê rîskê mezintir dike.', 'Nûvekirin qelsiyên hatine ragihandin digire. Piştî ku qelsî hat ragihandin, êrîşkar jî pê dizanin, ji ber vê yekê paşxistina sazkirinê rîskê mezintir dike.', 'Güncelleme duyurulmuş açıkları kapatır. Açık duyurulduktan sonra saldırganlar da onu bilir, bu yüzden kurulumu ertelemek riski büyütür.', 2, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=89349ae09406f253', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0042
('99ae18b2-c288-5a7c-afda-6a6da4901837', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Feydeya sereke ya rêvebirê şîfreyan çi ye?', 'Leza înternetê zêde dike', 'Vîrus û bernameyên fesadî ji pergalê radike', 'Ji bo her hesabê şîfreyeke cuda û xurt hiltîne', 'Pelên mezin piçûk dike', 'C', 'Bikarhêner tenê şîfreyeke sereke li bîra xwe digire, amûr yên din çêdike û hiltîne; bi vî awayî pêşî li bikaranîna heman şîfreyê li gelek malperan tê girtin.', 'Bikarhêner tenê şîfreyeke sereke li bîra xwe digire, amûr yên din çêdike û hiltîne; bi vî awayî pêşî li bikaranîna heman şîfreyê li gelek malperan tê girtin.', 'Kullanıcı tek bir ana parolayı hatırlar, araç geri kalanını üretip saklar; böylece aynı parolanın onlarca sitede tekrarlanması önlenir.', 2, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=258b4ebeb2ab2acc', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0043
('72ca0545-96c0-55e8-ad48-45f926162ba1', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Risk di tora Wi-Fi ya giştî de çi ye?', 'Kesên din dikarin trafîka neşîfrekirî bibînin', 'Bataryaya amûrê zû diqede', 'Pelên li ser dîskê bixweber tên jêbirin', 'Ekran hêdî hêdî tarî dibe', 'A', 'Di tora giştî de paket di heman derdorê re derbas dibin; di girêdaneke bêşîfre de kesek di navberê de dikare naverokê bixwîne. HTTPS û VPN vê rîskê gelekî kêm dikin.', 'Di tora giştî de paket di heman derdorê re derbas dibin; di girêdaneke bêşîfre de kesek di navberê de dikare naverokê bixwîne. HTTPS û VPN vê rîskê gelekî kêm dikin.', 'Ortak ağda paketler aynı ortamdan geçer; şifresiz bir bağlantıda aradaki biri içeriği okuyabilir. HTTPS ve VPN bu riski büyük ölçüde kapatır.', 3, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=5aba90cf3f6c8043', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0044
('ad1111a2-e5a0-5d48-b5c6-62f6826b77d6', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Kîjan nîşan e-nameyekê gumanbar dike?', 'Bikaranîna zimanekî fermî', 'Hebûna logoya sazîyê', 'Şandin di roja xebatê de', 'Daxwaza lezgîn a tikandina girêdanekê', 'D', 'Lezkirin fişareke klasîk e ku tê bikaranîn da ku qurbanî nefikire û rastiya wê kontrol neke. Logo, zimanê fermî û saeta şandinê bi hêsanî dikarin bên teqlîdkirin.', 'Lezkirin fişareke klasîk e ku tê bikaranîn da ku qurbanî nefikire û rastiya wê kontrol neke. Logo, zimanê fermî û saeta şandinê bi hêsanî dikarin bên teqlîdkirin.', 'Aceleye getirmek, kurbanın durup doğrulamasını engellemek için kullanılan klasik bir baskıdır. Logo, resmi dil ve gönderim saati kolayca taklit edilir.', 3, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=6591a72ce5d4ad6e', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0045
('82ae4d70-cfb9-51af-8b1d-ed998e283067', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Şîfrekirina daneyan çi peyda dike?', 'Daneyan bêyî mifteya rast nexwendî dike', 'Daneyan piçûktir dike', 'Daneyan zûtir vediguhêze', 'Daneyan bixweber li ser gelek amûran zêde dike', 'A', 'Şîfrekirin daneyan dixe formeke ku bêyî mifteyê nayên çareserkirin. Piçûkkirina mezinahiyê karê dewisandinê ye, derxistina kopiyan jî karê hilanîna ewlehiyê ye.', 'Şîfrekirin daneyan dixe formeke ku bêyî mifteyê nayên çareserkirin. Piçûkkirina mezinahiyê karê dewisandinê ye, derxistina kopiyan jî karê hilanîna ewlehiyê ye.', 'Şifreleme veriyi anahtarsız çözülemeyen bir biçime sokar. Boyutu küçültmek sıkıştırmanın, kopya çıkarmak ise yedeklemenin işidir.', 3, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=8dab849641340b93', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0046
('fe3b820d-8eb9-537f-aad0-3ab5947e77b7', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Nermalava fesadî ya bi navê ransomware çi dike?', 'Daneyên bikarhêner dizîne û bi nepenî dişîne', 'Reklaman bi zorê nîşan dide û gerokê diguherîne', 'Pelan şîfre dike û ji bo vekirinê pere dixwaze', 'Pergalê hêdî dike û pelên demkî çêdike', 'C', 'Nermalava fîdyeyê (ransomware) pelan şîfre dike û ji bo mifteyê pere dixwaze. Riya herî baş a xilasbûna bêyî dayîna pereyan, hebûna kopiyeke ewlehiyê ya rojane ye ku li cihekî cuda hatiye hilanîn.', 'Nermalava fîdyeyê (ransomware) pelan şîfre dike û ji bo mifteyê pere dixwaze. Riya herî baş a xilasbûna bêyî dayîna pereyan, hebûna kopiyeke ewlehiyê ya rojane ye ku li cihekî cuda hatiye hilanîn.', 'Fidye yazılımı dosyaları şifreleyip anahtar karşılığında ödeme ister. Güncel ve ayrı tutulan bir yedek, ödeme yapmadan kurtulmanın en sağlam yoludur.', 3, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=a59baee86e49e49e', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0047
('e9b05100-b3d6-5498-bdf9-ccb32984827a', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Kîjan rêbaza gava duyem li hember phishingê xurttir e?', 'Mifteya ewlehiyê ya fizîkî', 'Koda bi SMSê tê', 'Koda bi e-nameyê tê', 'Pirsa ewlehiyê ya kesane', 'A', 'Mifteya reqalavî navnîşana malperê jî piştrast dike, li malpereke derewîn bersivê nade. Lê kodê SMS û e-nameyê dikare ji aliyê bikarhêner ve li malpereke derewîn bê nivîsîn.', 'Mifteya reqalavî navnîşana malperê jî piştrast dike, li malpereke derewîn bersivê nade. Lê kodê SMS û e-nameyê dikare ji aliyê bikarhêner ve li malpereke derewîn bê nivîsîn.', 'Donanım anahtarı sitenin adresini de doğrular, sahte sayfaya yanıt vermez. SMS ve e-posta kodu ise kullanıcı tarafından sahte sayfaya yazılabilir.', 4, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=b67754f5e5d2b288', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0048
('26bad1a6-fb73-58d6-bb44-84304f48ffe1', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Zirara bikaranîna heman şîfreyê li gelek malperan çi ye?', 'Şîfre bi demê re bixweber dirêjtir û tevlihevtir dibe', 'Malper hêdîtir vedibin', 'Gerok şîfreyê ji bîr dike', 'Derketina daneyan a li yek malperê hesaban vedike', 'D', 'Êrîşkar navnîşa şîfreyên ku li cihekî derketine, bi awayekî otomatîk li malperên din diceribînin; gava saziyek tê hackkirin, hesabên din jî yek bi yek dikevin.', 'Êrîşkar navnîşa şîfreyên ku li cihekî derketine, bi awayekî otomatîk li malperên din diceribînin; gava saziyek tê hackkirin, hesabên din jî yek bi yek dikevin.', 'Saldırganlar bir yerde sızan parola listesini başka sitelerde otomatik dener; tek kurum ele geçtiğinde öteki hesaplar da peş peşe düşer.', 3, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=d3163f6cf87abc6b', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0049
('2a0c3e35-1dfe-5569-a55e-08bf6eda4d13', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Dîwarê agir (firewall) di torê de çi dike?', 'Trafîka têketî û derketî li gorî rêzikan fîltre dike', 'Pelên jêbirî vedigerîne', 'Şîfreyên qels xurt dike', 'Vîrusên li ser dîskê dibîne û qerantîne dike', 'A', 'Dîwarê agir li gorî qeydên ji berê ve hatine danîn biryar dide ka kîjan girêdan destûr digire. Paqijkirina nermalava xerab a di pelî de karê antîvîrusê ye.', 'Dîwarê agir li gorî qeydên ji berê ve hatine danîn biryar dide ka kîjan girêdan destûr digire. Paqijkirina nermalava xerab a di pelî de karê antîvîrusê ye.', 'Güvenlik duvarı hangi bağlantıya izin verileceğine önceden tanımlı kurallarla karar verir. Dosyadaki zararlıyı temizlemek antivirüsün işidir.', 3, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=b4d4ab9da60accf0', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0050
('5c4cab8b-1f89-5ddc-9db6-e64d5ca7da76', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Nîşana kilîtê ya li kêleka navnîşanê di gerokê de çi piştrast dike?', 'Malper ji aliyê dewletê ve hatiye pejirandin', 'Girêdan şîfrekirî ye', 'Agahiya li ser malperê rast e', 'Malper ji vîrusan paqij e', 'B', 'Nîşana kilîtê tenê dibêje ku trafîk şîfrekirî ye. Ji ber ku derewkar jî dikarin sertîfîkayê bistînin, ev nîşan wê wateyê nade ku malper rast an paqij e.', 'Nîşana kilîtê tenê dibêje ku trafîk şîfrekirî ye. Ji ber ku derewkar jî dikarin sertîfîkayê bistînin, ev nîşan wê wateyê nade ku malper rast an paqij e.', 'Kilit yalnızca trafiğin şifrelendiğini söyler. Sahtekârlar da sertifika alabildiği için simge sitenin dürüst ya da temiz olduğu anlamına gelmez.', 4, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=fbef8d46f7020c25', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0051
('928f3928-ac9b-5ee9-b7ec-d38f885a0096', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Çima divê kopiya ewlehiyê ji dem bi dem bi vegerandinê bê ceribandin?', 'Ji ber ku pelên di kopiyê de bi demê re mezintir dibin', 'Ji ber ku şîfre her mehê diguhere', 'Ji ber ku dîsk bi ceribandinê zûtir dibe', 'Ji ber ku kopiyeke xerabûyî tenê hingê xuya dibe', 'D', 'Kopiya ewlehiyê dikare bêdeng xera bibe; kêmasî an nexwendina pelî tenê dema ku vegerandin tê ceribandin diyar dibe. Dema karesatê ji bo fêrbûna vê yekê pir dereng e.', 'Kopiya ewlehiyê dikare bêdeng xera bibe; kêmasî an nexwendina pelî tenê dema ku vegerandin tê ceribandin diyar dibe. Dema karesatê ji bo fêrbûna vê yekê pir dereng e.', 'Yedekleme sessizce bozulabilir; dosyanın eksik ya da okunamaz olduğu ancak geri yükleme denenince anlaşılır. Felaket anı bunu öğrenmek için geç bir andır.', 3, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=488abb7eca31a955', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0052
('3c950678-6333-531a-b41a-e679c77770d9', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Gava kesek bi têlefonê şîfreya hesabê ji te dixwaze, tevgera rast çi ye?', 'Nîvê şîfreyê jê re gotin', 'Nedan û bi kanaleke fermî ya naskirî piştrastkirin', 'Şîfreyê guhertin û paşê ya nû bi têlefonê jê re gotin', 'Şîfreyê bi peyamekê şandin', 'B', 'Saziyan şîfreyê bi têlefonê naxwazin. Divê meriv ne li jimara ku telefon dike, li jimara fermî ya ku bi xwe dizane vegere; tewra parçeyeke şîfreyê jî ji êrîşkar re nîşaneyek dide.', 'Saziyan şîfreyê bi têlefonê naxwazin. Divê meriv ne li jimara ku telefon dike, li jimara fermî ya ku bi xwe dizane vegere; tewra parçeyeke şîfreyê jî ji êrîşkar re nîşaneyek dide.', 'Kurumlar parolayı telefonda istemez. Arayan numarayı değil kendi bildiğiniz resmî numarayı aramak gerekir; parolanın bir parçası bile saldırgana ipucu verir.', 1, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=5dbb54d06b32ab51', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0053
('38881cbf-9e9a-5cdc-ab43-9481ae7caf07', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Xetereya vekirina pêveka e-nameyeke nenas çi ye?', 'Nermalava fesadî li ser amûrê tê sazkirin', 'Bataryaya têlefonê zû diqede', 'E-name bixweber tê jêbirin', 'Navnîşana IPê diguhere', 'A', 'Gava pêvekek tê vekirin, dikare koda ku dixebite hilgire; pelên di rengê fatûre an belgeyê de bi vî awayî nermalava xerab dixin nav pergalê.', 'Gava pêvekek tê vekirin, dikare koda ku dixebite hilgire; pelên di rengê fatûre an belgeyê de bi vî awayî nermalava xerab dixin nav pergalê.', 'Ek dosya açıldığında çalışan kod taşıyabilir; fatura ya da belge kılığındaki dosyalar zararlıyı sisteme bu yolla sokar.', 2, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=ff29f3455e72ada8', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0054
('4d4cc89f-d5b0-5165-9f76-74242672a091', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Şîfrekirina serî-bi-serî tê çi wateyê?', 'Tenê server dikare peyaman bixwîne', 'Tenê şander û wergir dikarin peyaman bixwînin', 'Peyam tenê bi girêdana zexm tên şandin', 'Peyam piştî demekê bixweber tên jêbirin', 'B', 'Mifteya çareseriyê tenê li cîhazên li her du aliyan dimîne; tewra serverê ku peyamê digihîne jî nikare naverokê veke. Jêbirina bixweber taybetmendiyeke cuda ye ji vê.', 'Mifteya çareseriyê tenê li cîhazên li her du aliyan dimîne; tewra serverê ku peyamê digihîne jî nikare naverokê veke. Jêbirina bixweber taybetmendiyeke cuda ye ji vê.', 'Çözme anahtarı yalnız iki uçtaki cihazlarda durur; iletiyi taşıyan sunucu bile içeriği açamaz. Kendiliğinden silinme bundan ayrı bir özelliktir.', 4, true, 'multiple_choice', NULL, NULL, 'Teknolojiya bingehîn — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_core#gate=validate_batch.py#hash=c7bf276b4f692f82', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_core_0055
('08463ac0-ae76-5ba9-adeb-626929ed5f96', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Di derdora sala 1450an de li Ewrûpayê makîneya çapê ya bi tîpên livok kî pêş xist?', 'Johannes Gutenberg', 'Nicolaus Copernicus', 'Isaac Newton', 'Leonardo da Vinci', 'A', 'Gutenberg tîpên metal ên rêtî yek bi yek xiste kelûpeleke ku dihate rêzkirin; bi vî awayî rûpelek li şûna ku bi rojan bi destan bihata nivîsîn, bi sedan caran hate çapkirin. Kopernîk bi astronomiyê, Newton bi fizîkê, da Vinci jî bi wêne û xêzên endezyariyê tê nasîn.', 'Gutenberg tîpên metal ên rêtî yek bi yek xiste kelûpeleke ku dihate rêzkirin; bi vî awayî rûpelek li şûna ku bi rojan bi destan bihata nivîsîn, bi sedan caran hate çapkirin. Kopernîk bi astronomiyê, Newton bi fizîkê, da Vinci jî bi wêne û xêzên endezyariyê tê nasîn.', 'Gutenberg dökme metal harfleri tek tek dizilebilen bir kalıba oturttu; böylece bir sayfa günlerce elle yazılmak yerine yüzlerce kez basılabildi. Kopernik gökbilimle, Newton fizikle, da Vinci ise resim ve mühendislik taslaklarıyla anılır.', 1, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=48227cd643aa2caf', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0001
('7a2b88ba-6078-5a37-b67c-581a12d4fc3c', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Di sala 1876an de patenta telefonê bi navê kê hat qeydkirin?', 'Wilhelm Conrad Röntgen', 'Samuel Morse', 'Guglielmo Marconi', 'Alexander Graham Bell', 'D', 'Bell di sala 1876an de patenta amûra ku axaftinê vediguherîne sînyala elektrîkê stend û pargîdaniya telefonê ya yekem damezrand. Morse bi alfabeya telgrafê, Marconî bi telsizê, Röntgen jî bi tîrêjên X têne nasîn.', 'Bell di sala 1876an de patenta amûra ku axaftinê vediguherîne sînyala elektrîkê stend û pargîdaniya telefonê ya yekem damezrand. Morse bi alfabeya telgrafê, Marconî bi telsizê, Röntgen jî bi tîrêjên X têne nasîn.', 'Bell, konuşmayı elektrik sinyaline çeviren aygıtın patentini 1876''da aldı ve ilk telefon şirketini kurdu. Morse telgraf alfabesiyle, Marconi telsizle, Röntgen ise X ışınlarıyla anılır.', 2, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=73e70e6b87ac3fdf', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0002
('675e5dc8-554e-53d6-8e03-19d6de96bc29', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Transîstor di sala 1947an de li kîjan laboratûwarê hat pêşxistin?', 'Bell Labs', 'Laboratûwara Cavendish', 'Laboratûwara Los Alamos', 'CERN', 'A', 'Di sala 1947an de li Laboratûwarên Bell, Bardeen, Brattain û Shockley transîstora yekem a ku bi germanyûmê dixebite pêşkêş kirin; ev amûr şûna tûpên vakumê girt. CERN li ser fizîka perçikan, Los Alamos jî li ser lêkolîna nukleerî hûr dibe.', 'Di sala 1947an de li Laboratûwarên Bell, Bardeen, Brattain û Shockley transîstora yekem a ku bi germanyûmê dixebite pêşkêş kirin; ev amûr şûna tûpên vakumê girt. CERN li ser fizîka perçikan, Los Alamos jî li ser lêkolîna nukleerî hûr dibe.', '1947''de Bell Laboratuvarları''nda Bardeen, Brattain ve Shockley germanyumla çalışan ilk transistoru gösterdi; bu aygıt vakum tüplerinin yerini aldı. CERN parçacık fiziğine, Los Alamos nükleer araştırmaya odaklıdır.', 3, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=0fd78c821a4b2ca7', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0003
('4c6f3909-cb1e-5b04-a813-6bb2b50ca3ae', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Di 1879an de li Amerîkayê ampûla elektrîkê ya ku demeke dirêj dişewitî kê pêş xist?', 'Nikola Tesla', 'Michael Faraday', 'Thomas Edison', 'Alessandro Volta', 'C', 'Tîma Edîson di sala 1879an de bi fîlamana karbonê ya berxwedaneke bilind ampûlek çêkir ku bi saetan dişewitî û ev bi pergaleke belavkirina elektrîkê ve girêda. Volta bi pîlê, Faraday bi endûksiyonê, Tesla jî bi motorên cereyana alternatîf têne nasîn.', 'Tîma Edîson di sala 1879an de bi fîlamana karbonê ya berxwedaneke bilind ampûlek çêkir ku bi saetan dişewitî û ev bi pergaleke belavkirina elektrîkê ve girêda. Volta bi pîlê, Faraday bi endûksiyonê, Tesla jî bi motorên cereyana alternatîf têne nasîn.', 'Edison''un ekibi 1879''da yüksek dirençli karbon flamanla saatlerce yanan bir ampul üretti ve bunu bir elektrik dağıtım sistemiyle birleştirdi. Volta pili, Faraday indüksiyonu, Tesla ise alternatif akım motorlarıyla anılır.', 3, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=2d8e2210257f2d39', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0004
('745e78cc-3031-50a4-810c-39865785c3e5', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Rêbaza wênekêşiyê ya ku di sala 1839an de li Fransayê hat ragihandin bi navê kê tê nasîn?', 'Louis Daguerre', 'George Eastman', 'Joseph Swan', 'Auguste Lumière', 'A', 'Ev rêbaza ku li ser lewheya sifir a bi zîv hatiye pêçandin tê tomarkirin, bi navê pêşxerê xwe wek dagerotîp tê nasîn. Eastman fîlmê rûlok belav kir, birayên Lumière sînemayê pêş xistin, Swan jî bi xebatên xwe yên li ser ampûlê tê nasîn.', 'Ev rêbaza ku li ser lewheya sifir a bi zîv hatiye pêçandin tê tomarkirin, bi navê pêşxerê xwe wek dagerotîp tê nasîn. Eastman fîlmê rûlok belav kir, birayên Lumière sînemayê pêş xistin, Swan jî bi xebatên xwe yên li ser ampûlê tê nasîn.', 'Gümüş kaplı bakır levhaya kaydedilen bu yöntem, geliştiricisinin adıyla dagerotip diye anılır. Eastman rulo filmi yaygınlaştırdı, Lumière kardeşler sinemayı, Swan ise ampul çalışmalarını temsil eder.', 3, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=b090e0ccc1cea2f6', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0005
('f2f60cce-6e45-55e1-93b8-b12db97eddbb', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Gutenberg çapxaneya xwe ya bi tîpên livok li kîjan bajarê Almanyayê damezrand?', 'Köln', 'Nürnberg', 'Frankfurt', 'Mainz', 'D', 'Gutenberg li Mainzê ji dayik bû û Încîla xwe ya navdar a 42 rêzikan li wir çap kir. Nürnberg û Frankfurt paşê bûne navendên mezin ên weşangeriyê, lê kargeha yekem li Mainzê bû.', 'Gutenberg li Mainzê ji dayik bû û Încîla xwe ya navdar a 42 rêzikan li wir çap kir. Nürnberg û Frankfurt paşê bûne navendên mezin ên weşangeriyê, lê kargeha yekem li Mainzê bû.', 'Gutenberg Mainz''de doğdu ve ünlü 42 satırlık İncil''i orada bastı. Nürnberg ile Frankfurt sonradan büyük yayın merkezleri oldu, ama ilk atölye Mainz''deydi.', 4, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=91873e8f0f5bef57', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0006
('bfca073c-fcb7-5da2-b353-61f018efd1d0', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Amûra fonografê ya ku dengê tomarkirî ji nû ve lê dixe di sala 1877an de ji aliyê kê ve hat çêkirin?', 'Thomas Edison', 'Emile Berliner', 'Werner von Siemens', 'Guglielmo Marconi', 'A', 'Edîson deng bi derziyekê li ser silindirek ji pelika teneke tomar kir û bi heman derziyê dîsa lê da. Berliner paşê plaka dûz pêş xist; Siemens li ser makîneyên elektrîkê, Marconî jî li ser telsizê xebitî.', 'Edîson deng bi derziyekê li ser silindirek ji pelika teneke tomar kir û bi heman derziyê dîsa lê da. Berliner paşê plaka dûz pêş xist; Siemens li ser makîneyên elektrîkê, Marconî jî li ser telsizê xebitî.', 'Edison sesi kalay yapraklı bir silindire iğneyle çizerek kaydetti ve aynı iğneyle geri çaldı. Berliner sonradan düz plağı geliştirdi; Siemens elektrik makineleri, Marconi telsiz üzerine çalıştı.', 3, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=6890899064168379', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0007
('d2183463-1d35-5917-8a56-678a9ecb3ea6', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Transîstora yekem a sala 1947an ji kîjan maddeya nîv-derbasker hat çêkirin?', 'Sîlîkon', 'Selenyûm', 'Germanyûm', 'Galyûm arsenît', 'C', 'Transîstora yekem a xala-pêwendiyê li ser krîstala germanyûmê hate avakirin; sîlîkon tenê di salên 1950î de, gava paqijkirin hêsantir bû, derket pêş. Galyûm arsenît madeya çerxên leza bilind ên gelekî paşerojtir e.', 'Transîstora yekem a xala-pêwendiyê li ser krîstala germanyûmê hate avakirin; sîlîkon tenê di salên 1950î de, gava paqijkirin hêsantir bû, derket pêş. Galyûm arsenît madeya çerxên leza bilind ên gelekî paşerojtir e.', 'İlk nokta temaslı transistor germanyum kristali üzerine kuruldu; silisyum ancak 1950''lerde saflaştırma kolaylaşınca öne geçti. Galyum arsenit çok daha sonraki yüksek hızlı devrelerin malzemesidir.', 4, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=6954e9d5960394cd', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0008
('3746ec1e-195b-50de-8b5e-b782b28b3f81', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Alfabeya xet û xalan a ku di telegrafê de tê bikaranîn bi navê kîjan dahêner tê nasîn?', 'Samuel Morse', 'Charles Wheatstone', 'Alexander Graham Bell', 'Thomas Edison', 'A', 'Morse û hevalê xwe Alfred Vail koda ku tîpan vediguherîne sînyalên kurt û dirêj amade kirin; telgrafa yek-têl bi vê kodê fehmbar bû. Wheatstone pergaleke telgrafê ya cuda ya pir-derzî ava kiribû.', 'Morse û hevalê xwe Alfred Vail koda ku tîpan vediguherîne sînyalên kurt û dirêj amade kirin; telgrafa yek-têl bi vê kodê fehmbar bû. Wheatstone pergaleke telgrafê ya cuda ya pir-derzî ava kiribû.', 'Morse ve arkadaşı Alfred Vail harfleri kısa ve uzun sinyallere çeviren bir kod düzenledi; tek telli telgraf bu kodla anlaşılır oldu. Wheatstone çok iğneli farklı bir telgraf sistemi kurmuştu.', 2, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=f0f6a148039a7c03', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0009
('05f96481-eccf-5b1d-a979-d011d4394186', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Di sala 1895an de tîrêjên X kê keşf kirin?', 'Henri Becquerel', 'Wilhelm Röntgen', 'Marie Curie', 'J.J. Thomson', 'B', 'Röntgen dema ku bi tûpa tîrêjên katodê dixebitî, ekraneke ku di tarîtiyê de dibiriqî dît û navê X li tîrêja nenas kir; ev vedîtin di sala 1901ê de Xelata Nobelê ya yekem a Fizîkê wergirt. Becquerel û Curie li ser radyoaktîfiyê, Thomson jî li ser elektronê xebitîn.', 'Röntgen dema ku bi tûpa tîrêjên katodê dixebitî, ekraneke ku di tarîtiyê de dibiriqî dît û navê X li tîrêja nenas kir; ev vedîtin di sala 1901ê de Xelata Nobelê ya yekem a Fizîkê wergirt. Becquerel û Curie li ser radyoaktîfiyê, Thomson jî li ser elektronê xebitîn.', 'Röntgen katot ışını tüpüyle çalışırken karanlıkta parlayan bir ekran fark etti ve bilinmeyen ışına X adını verdi; bu buluş 1901''de ilk Nobel Fizik Ödülü''nü kazandı. Becquerel ve Curie radyoaktiflik, Thomson elektron üzerine çalıştı.', 3, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=80f1c0cbbf702159', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0010
('629770cc-07e3-55e8-8187-b635f01aedfa', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Di sala 1901ê de yekem sînyala radyoyî ya di ser Atlantîkê re ji aliyê kê ve hat wergirtin?', 'Guglielmo Marconi', 'Heinrich Hertz', 'Nikola Tesla', 'Alexander Graham Bell', 'A', 'Marconî sînyala ku ji Îngilîstanê hatibû şandin li Newfoundlandê bi anteneke bi bafirokê ve daliqandî girt û nîşan da ku telsiz dikare li ser okyanûsê bixebite. Hertz pêlên radyoyê li laboratuwarê îspat kiribû, lê pergaleke ragihandinê ava nekiribû.', 'Marconî sînyala ku ji Îngilîstanê hatibû şandin li Newfoundlandê bi anteneke bi bafirokê ve daliqandî girt û nîşan da ku telsiz dikare li ser okyanûsê bixebite. Hertz pêlên radyoyê li laboratuwarê îspat kiribû, lê pergaleke ragihandinê ava nekiribû.', 'Marconi, İngiltere''den gönderilen sinyali Newfoundland''da uçurtmaya asılı antenle yakaladı ve telsizin okyanus aşırı çalışabildiğini gösterdi. Hertz radyo dalgalarını laboratuvarda kanıtlamıştı ama iletişim sistemi kurmadı.', 4, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=90b47f63abb64743', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0011
('732a40f0-cdb5-5d8d-a15f-7ea5d8da7b8b', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Kîjan zanyar hem ji bo transîstorê hem jî ji bo teoriya supernaqilbariyê Xelata Nobelê ya Fizîkê wergirt?', 'Walter Brattain', 'John Bardeen', 'William Shockley', 'Robert Noyce', 'B', 'Bardeen di sala 1956an de ji bo transîstorê, di 1972yan de jî ji bo teoriya supernaqilbariya BCS Xelata Nobelê wergirt û bû yekane kesê ku du caran di fizîkê de Nobel wergirtiye. Brattain û Shockley tenê xelata 1956an parve kirin; Noyce bi xebatên li ser çerxên hevgirtî tê nasîn.', 'Bardeen di sala 1956an de ji bo transîstorê, di 1972yan de jî ji bo teoriya supernaqilbariya BCS Xelata Nobelê wergirt û bû yekane kesê ku du caran di fizîkê de Nobel wergirtiye. Brattain û Shockley tenê xelata 1956an parve kirin; Noyce bi xebatên li ser çerxên hevgirtî tê nasîn.', 'Bardeen 1956''da transistor, 1972''de BCS süperiletkenlik kuramıyla ödül aldı ve fizikte iki Nobel kazanan tek kişi oldu. Brattain ile Shockley yalnız 1956 ödülünü paylaştı; Noyce tümleşik devre çalışmalarıyla anılır.', 5, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=1beba113cc34f89c', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0012
('c765a5ea-b0a7-57d4-b366-b21bdaf8df16', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Belavbûna makîneya çapê di sedsala 15an de bi taybetî çi erzan kir?', 'Cam', 'Kinc', 'Kaxez', 'Pirtûk', 'D', 'Ji ber ku tîpên rêzkirî heta çapkirina bi sedan kopyan di kelûpelê de diman, lêçûna nivîsekê li gorî ji-nû-nivîsandina bi destan pir kêm bû. Hilberîna cam, cil û kaxezê ne bi vê makîneyê, lê bi pêşketina teknolojiyên wan ên taybet erzan bû.', 'Ji ber ku tîpên rêzkirî heta çapkirina bi sedan kopyan di kelûpelê de diman, lêçûna nivîsekê li gorî ji-nû-nivîsandina bi destan pir kêm bû. Hilberîna cam, cil û kaxezê ne bi vê makîneyê, lê bi pêşketina teknolojiyên wan ên taybet erzan bû.', 'Dizilen harfler yüzlerce kopya basılana dek kalıpta kaldığı için bir metnin maliyeti elle çoğaltmaya göre çok düştü. Cam, giysi ve kâğıt üretimi bu makineyle değil, kendi zanaatlarının gelişimiyle ucuzladı.', 1, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=aa2460c84dba6c61', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0013
('0d92b182-62d4-5955-8a23-01cb9403a27f', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Pîla yekem a ku di sala 1800î de cereyanek berdewam da kî çêkir?', 'André-Marie Ampère', 'Alessandro Volta', 'Georg Ohm', 'Michael Faraday', 'B', 'Volta bi rêzkirina lewheyên zînk û sifir bi qumaşê xwêdar li ser hev cereyaneke bêrawestan çêkir; ev kom çavkaniya yekem bû ku enerjiya kîmyewî vediguherîne elektrîkê. Ohm têkiliya berxwedanê, Ampère cereyanê, Faraday jî endûksiyonê lêkolîn kirin.', 'Volta bi rêzkirina lewheyên zînk û sifir bi qumaşê xwêdar li ser hev cereyaneke bêrawestan çêkir; ev kom çavkaniya yekem bû ku enerjiya kîmyewî vediguherîne elektrîkê. Ohm têkiliya berxwedanê, Ampère cereyanê, Faraday jî endûksiyonê lêkolîn kirin.', 'Volta çinko ve bakır levhaları tuzlu bezle üst üste dizerek kesintisiz akım üretti; bu yığın kimyasal enerjiyi elektriğe çeviren ilk kaynaktı. Ohm direnç bağıntısını, Ampère akımı, Faraday indüksiyonu inceledi.', 3, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=cdf1f9c8df21d2be', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0014
('9e13f36b-414a-58c3-885e-a4e972276f91', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Kê di sala 1831ê de nîşan da ku mîknatîseke di tevgerê de di têlekê de cereyanê çêdike?', 'Michael Faraday', 'James Clerk Maxwell', 'Heinrich Hertz', 'Hans Christian Ørsted', 'A', 'Ceribandinên endûksiyonê yên Faraday bingeha jeneratorê û transformatorê ne. Ørsted berevajiyê vê dît, ku cereyan derziya pûsulayê dilivîne; Maxwell ev têkilî bi hevkêşeyan nivîsî, Hertz jî pêlan pîve.', 'Ceribandinên endûksiyonê yên Faraday bingeha jeneratorê û transformatorê ne. Ørsted berevajiyê vê dît, ku cereyan derziya pûsulayê dilivîne; Maxwell ev têkilî bi hevkêşeyan nivîsî, Hertz jî pêlan pîve.', 'Faraday''ın indüksiyon deneyleri jeneratörün ve transformatörün temelidir. Ørsted bunun tersini, akımın pusula iğnesini saptırdığını bulmuştu; Maxwell bu ilişkileri denklemlerle yazdı, Hertz ise dalgaları ölçtü.', 3, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=ce92f4ae9c385d82', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0015
('72a19c45-c030-5df1-9035-cdbd18bd011c', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Yekîneya hêzê ya bi navê wat ji navê kîjan endezyarî tê?', 'Rudolf Diesel', 'James Watt', 'Nikolaus Otto', 'George Stephenson', 'B', 'Watt bi lêzêdekirina kondansatoreke cuda li makîneya hilmê, karîgeriya wê pir zêde kir; yekîneya hêzê bi bîranîna wî hate navkirin. Otto û Dîzel bi motorên şewitandina hundir, Stephenson jî bi lokomotîfê têne nasîn.', 'Watt bi lêzêdekirina kondansatoreke cuda li makîneya hilmê, karîgeriya wê pir zêde kir; yekîneya hêzê bi bîranîna wî hate navkirin. Otto û Dîzel bi motorên şewitandina hundir, Stephenson jî bi lokomotîfê têne nasîn.', 'Watt, buhar makinesine ayrı bir yoğuşturucu ekleyerek verimini büyük ölçüde artırdı; güç birimi onun anısına adlandırıldı. Otto ve Diesel içten yanmalı motorlarla, Stephenson lokomotifle anılır.', 2, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=2e50e4a7094abfdd', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0016
('174047d3-f77b-5ff6-ac5f-bbb253d0e648', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Motora elektrîkê enerjiya elektrîkê vediguherîne kîjan cûre enerjiyê?', 'Enerjiya kîmyewî', 'Enerjiya ronahiyê', 'Enerjiya nukleerî', 'Enerjiya mekanîkî', 'D', 'Di motorê de bobîna ku cereyanê digire ji qada mîknatîsî hêzê distîne û mîl dizivire; encama derketî tevger e. Veguherîna kîmyewî di pîlê de, ronahî di lambeyê de, veguherîna nukleerî jî di reaktorê de çêdibe.', 'Di motorê de bobîna ku cereyanê digire ji qada mîknatîsî hêzê distîne û mîl dizivire; encama derketî tevger e. Veguherîna kîmyewî di pîlê de, ronahî di lambeyê de, veguherîna nukleerî jî di reaktorê de çêdibe.', 'Motorda akım taşıyan sargı manyetik alandan kuvvet görür ve mil döner; çıkan ürün harekettir. Kimyasal dönüşüm pilde, ışık lambada, nükleer dönüşüm ise reaktörde olur.', 1, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=9f1e4f1800969fe2', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0017
('aa6c25f3-25a5-5949-aa56-22007919971b', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Di santralekê de kîjan cîhaz tevgera dorînê dike elektrîk?', 'Transformator', 'Jenerator', 'Kondansator', 'Rezîstans', 'B', 'Di jeneratorê de bobîna ku tê zivirandin di nav qada mîknatîsî de cereyaneke endûksiyonê çêdike. Transformator voltajê diguherîne, kondansator barê hildide, berxwedan jî cereyanê sînordar dike.', 'Di jeneratorê de bobîna ku tê zivirandin di nav qada mîknatîsî de cereyaneke endûksiyonê çêdike. Transformator voltajê diguherîne, kondansator barê hildide, berxwedan jî cereyanê sînordar dike.', 'Jeneratörde döndürülen sargı manyetik alan içinde indüksiyon akımı üretir. Transformatör gerilimi değiştirir, kondansatör yük depolar, direnç ise akımı sınırlar.', 2, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=e771f263f335468c', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0018
('b2edc132-66ae-55de-aea7-bb6ca01616cd', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Li gorî qanûna Ohm, voltaj bi kîjan hesabê tê dîtin?', 'V = I × R', 'V = I ÷ R', 'V = R ÷ I', 'V = I × R²', 'A', 'Voltaj bi encama lêkdana cereyan û berxwedanê wekhev e; dema berxwedan sabît be, du qatkirina cereyanê voltajê jî du qat dike. Formên dabeşkirî xelet in, forma bi R² jî bi hesabê hêzê re hatiye tevlîhevkirin.', 'Voltaj bi encama lêkdana cereyan û berxwedanê wekhev e; dema berxwedan sabît be, du qatkirina cereyanê voltajê jî du qat dike. Formên dabeşkirî xelet in, forma bi R² jî bi hesabê hêzê re hatiye tevlîhevkirin.', 'Gerilim, akım ile direncin çarpımına eşittir; direnç sabitken akımı iki katına çıkarmak gerilimi de iki katına çıkarır. Bölmeli biçimler birimleri tutturmaz, karesi alınmış biçim ise güç hesabından karışmıştır.', 3, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=9f6464777c0e92f6', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0019
('b84dd64d-3450-51a4-bd44-eb1de5897a75', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Tirbîna bayê enerjiya kîjan çavkaniyê digire da ku elektrîkê çêbike?', 'Germahiya kûrahiya erdê', 'Tevgera hewayê', 'Tîrêja rojê', 'Herikîna avê', 'B', 'Enerjiya kînetîk a bayê perikên tîrbînê dizivirîne, mîl jî jeneratorê dizivirîne. Herikîna avê di hîdroelektrîkê de, germahiya erdê di jeotermalê de, tîrêja rojê jî di panelan de tê bikaranîn.', 'Enerjiya kînetîk a bayê perikên tîrbînê dizivirîne, mîl jî jeneratorê dizivirîne. Herikîna avê di hîdroelektrîkê de, germahiya erdê di jeotermalê de, tîrêja rojê jî di panelan de tê bikaranîn.', 'Esen havanın kinetik enerjisi kanatları döndürür, mil de jeneratörü çevirir. Su akışı hidroelektrikte, yer ısısı jeotermalde, güneş ışığı ise panellerde kullanılır.', 1, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=a1c631f6d30f658d', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0020
('7a3698bb-8550-578e-9bdb-8e283a991ea2', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Hucreyên fotovoltaîk ên panelên rojê bi piranî ji kîjan maddeyê têne çêkirin?', 'Sifir', 'Alumînyûm', 'Sîlîkon', 'Zînk', 'C', 'Sîlîkon nîv-derbasker e; gava ronahî tê mijîn, elektronên wê azad dimînin û di çerxê de cereyan çêdibe. Sifir û alûmînyûm tenê derbasker in, zînk jî madeya pîl û pêçanê ye.', 'Sîlîkon nîv-derbasker e; gava ronahî tê mijîn, elektronên wê azad dimînin û di çerxê de cereyan çêdibe. Sifir û alûmînyûm tenê derbasker in, zînk jî madeya pîl û pêçanê ye.', 'Silisyum yarı iletkendir; ışık soğurulunca elektronları serbest kalır ve devrede akım doğar. Bakır ile alüminyum yalnız iletken, çinko ise pil ve kaplama malzemesidir.', 3, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=8546c0bafe68d827', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0021
('f573fa84-fbf6-5eca-99e7-d7e30561f14a', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Di santrala hîdroelektrîkê de ava li pişt bendavê di destpêkê de kîjan enerjiyê hildigire?', 'Enerjiya potansiyel', 'Enerjiya kîmyewî', 'Enerjiya germî ya hawirdorê', 'Enerjiya ronahiyê', 'A', 'Ava ku li bilindiyê tê girtin enerjiya potansiyel a rakêşiyê hildide; dema ku ji boriyê dadikeve, ev enerjî vediguhere tevgerê, di tîrbînê de jî vediguhere elektrîkê. Germahî û enerjiya kîmyewî nirxên têketî yên cureyên din ên santralan in.', 'Ava ku li bilindiyê tê girtin enerjiya potansiyel a rakêşiyê hildide; dema ku ji boriyê dadikeve, ev enerjî vediguhere tevgerê, di tîrbînê de jî vediguhere elektrîkê. Germahî û enerjiya kîmyewî nirxên têketî yên cureyên din ên santralan in.', 'Yüksekte tutulan su yerçekimi potansiyel enerjisi depolar; borudan düşerken bu enerji harekete, türbinde de elektriğe dönüşür. Isı ve kimyasal enerji başka santral türlerinin girdisidir.', 3, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=a02d419bc2cae1e5', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0022
('f9ab56e6-c07b-5cdc-a335-8b86b819f229', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Makîneyeke sade hêza pêwîst kêm dike; lê di berdêla wê de çi zêde dibe?', 'Karê ku tê kirin', 'Enerjiya ku tê xerckirin', 'Dûrahiya rêwîtiya hêzê', 'Girseya barê', 'C', 'Kar hasilê hêz û rê ye; dema makîne hêzê piçûk dike, ji bo heman karî bike, rê dirêj dike. Heke hevkişandin tune be, tevahiya kar û enerjî naguhere, girseya barê jî wek xwe dimîne.', 'Kar hasilê hêz û rê ye; dema makîne hêzê piçûk dike, ji bo heman karî bike, rê dirêj dike. Heke hevkişandin tune be, tevahiya kar û enerjî naguhere, girseya barê jî wek xwe dimîne.', 'İş, kuvvet ile yolun çarpımıdır; makine kuvveti küçültürken aynı işi yapabilmek için yolu uzatır. Sürtünme yoksa toplam iş ve enerji değişmez, yükün kütlesi de aynı kalır.', 3, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=aab3cca1e9a4f7bb', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0023
('8f136a06-65cc-52f1-a1b7-e714e4be23cd', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Transformator di tora elektrîkê de bi taybetî çi diguherîne?', 'Frekansa cereyanê', 'Asta voltajê', 'Aliyê cereyanê', 'Cûreya têla derbasker', 'B', 'Rêjeya hejmara zivirandinê ya di navbera du bobînan de voltajê bilind an nizim dike; frekans wek xwe dimîne. Guherandina alî karê rastkerê ye, cureyê derbasker jî di sazkirina tesîsatê de tê diyarkirin.', 'Rêjeya hejmara zivirandinê ya di navbera du bobînan de voltajê bilind an nizim dike; frekans wek xwe dimîne. Guherandina alî karê rastkerê ye, cureyê derbasker jî di sazkirina tesîsatê de tê diyarkirin.', 'İki sargı arasındaki sarım sayısı oranı gerilimi yükseltir ya da düşürür; frekans aynı kalır. Yön çevirme doğrultucunun işidir, iletken cinsi ise tesisatın kurulumunda belirlenir.', 3, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=c3378e54203a5bee', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0024
('6f5d7018-2dce-5e2e-a93f-49a1a0c93673', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Ji van maddeyan kîjan ji bo têlên elektrîkê baştirîn derbasker e?', 'Cam', 'Lastîk', 'Sifir', 'Dar', 'C', 'Di sifir de elektronên azad zêde ne, ji ber vê yekê cereyanê bi kêm windabûnê digihîne. Cam, lastîk û dar îzolator in; ew jixwe ji bo rawestandina cereyanê têne bikaranîn.', 'Di sifir de elektronên azad zêde ne, ji ber vê yekê cereyanê bi kêm windabûnê digihîne. Cam, lastîk û dar îzolator in; ew jixwe ji bo rawestandina cereyanê têne bikaranîn.', 'Bakırda serbest elektronlar boldur, bu yüzden akımı az kayıpla taşır. Cam, lastik ve ahşap yalıtkandır; zaten akımı durdurmak için kullanılırlar.', 2, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=0ab36b54617bdc28', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0025
('60e074c2-4400-525d-ab8a-d71321a3b646', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Hêza elektrîkî ya amûrekê bi kîjan formûlê tê hesibandin?', 'Voltaj × cereyan', 'Voltaj ÷ cereyan', 'Cereyan × berxwedan', 'Voltaj × berxwedan', 'A', 'Hêz, enerjiya di yekîneya demê de tê veguhastin e û bi hevberdana voltaj û cereyanê wekhev e; encam bi watt derdikeve. Hevberdana cereyan û berxwedanê voltajê dide, ne hêzê.', 'Hêz, enerjiya di yekîneya demê de tê veguhastin e û bi hevberdana voltaj û cereyanê wekhev e; encam bi watt derdikeve. Hevberdana cereyan û berxwedanê voltajê dide, ne hêzê.', 'Güç, birim zamanda aktarılan enerjidir ve gerilim ile akımın çarpımına eşittir; sonuç watt cinsinden çıkar. Akım ile direncin çarpımı gerilimi verir, gücü değil.', 3, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=70d670e39d6f59f1', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0026
('42bba2f2-756f-52bb-8b34-b1ae8d2193b4', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Di çerxeke rêzî de ji bo her hêmanekê çi wekhev dimîne?', 'Voltaja her hêmanê', 'Hêza her hêmanê', 'Cereyana ku diherike', 'Berxwedana her hêmanê', 'C', 'Di çerxeke rêzî de ji bo barê tenê rêyek heye, ji ber vê yekê cereyan li her xalê wekhev e; voltaj jî li gorî rêjeya berxwedanan tê parvekirin. Di girêdana paralel de berevajî vê, voltaj hevpar dimîne.', 'Di çerxeke rêzî de ji bo barê tenê rêyek heye, ji ber vê yekê cereyan li her xalê wekhev e; voltaj jî li gorî rêjeya berxwedanan tê parvekirin. Di girêdana paralel de berevajî vê, voltaj hevpar dimîne.', 'Seri devrede yük için tek bir yol vardır, bu yüzden akım her noktada eşittir; gerilim ise dirençlerin oranına göre bölüşülür. Paralel bağlantıda tam tersine gerilim ortak olur.', 4, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=066cd822b054b0d7', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0027
('532990a7-c374-570c-be04-52088852fcd8', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Sîgorta di çerxeke elektrîkê de ji bo çi tê danîn?', 'Ji bo bilindkirina voltajê', 'Ji bo birîna cereyana zêde', 'Ji bo hilanîna enerjiyê', 'Ji bo nizmkirina frekansê', 'B', 'Têla zirav a di sîgortayê de gava cereyan ji astekê zêdetir be germ dibe û dihele û çerxê vedike; bi vî awayî kabel naşewitin. Bilindkirina voltajê karê transformatorê ye, hilanîna enerjiyê jî karê pîlê ye.', 'Têla zirav a di sîgortayê de gava cereyan ji astekê zêdetir be germ dibe û dihele û çerxê vedike; bi vî awayî kabel naşewitin. Bilindkirina voltajê karê transformatorê ye, hilanîna enerjiyê jî karê pîlê ye.', 'Sigortadaki ince tel belirli bir akımın üstünde ısınıp erir ve devreyi açar; böylece kablolar yanmaz. Gerilim yükseltmek transformatörün, enerji depolamak pilin işidir.', 3, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=6a23b7ea961cf9a1', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0028
('24b107e3-4c28-5d6e-bf70-8fed4918c355', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Di santrala germî ya komirê de tirbîn rasterast bi çi tê zivirandin?', 'Dûmana germ a komirê', 'Ava sar', 'Hilma bin zextê', 'Bayê derve', 'C', 'Komir avê dikelîne, hilma bi zexteke bilind li perikên tîrbînê dide û mîlê dizivirîne. Dûman bermayî ye ku ji bacê tê avêtin; ava sar jî di çerxeke cuda de digere da ku hilmê bike av.', 'Komir avê dikelîne, hilma bi zexteke bilind li perikên tîrbînê dide û mîlê dizivirîne. Dûman bermayî ye ku ji bacê tê avêtin; ava sar jî di çerxeke cuda de digere da ku hilmê bike av.', 'Kömür suyu kaynatır, yüksek basınçlı buhar türbin kanatlarına çarparak mili döndürür. Duman bacadan atılan atıktır; soğuk su ise buharı yoğuşturmak için ayrı bir devrede dolaşır.', 4, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=a0f615eff43fc7d5', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0029
('5719b22a-8138-581d-b105-e1b82fea3f08', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Pîlek dema kar dike enerjiya kîmyewî vediguherîne çi?', 'Enerjiya germî ya rasterast', 'Enerjiya ronahiyê', 'Enerjiya dengî', 'Enerjiya elektrîkî', 'D', 'Reaksiyona kîmyewî ya di navbera du elektrodên pîlê de elektronan ber bi çerxa derve ve dide û cereyan çêdibe. Germahî tenê windahiyeke piçûk a alîkî ye; ronahî tenê dema lampeyek bi çerxê ve were girêdan derdikeve.', 'Reaksiyona kîmyewî ya di navbera du elektrodên pîlê de elektronan ber bi çerxa derve ve dide û cereyan çêdibe. Germahî tenê windahiyeke piçûk a alîkî ye; ronahî tenê dema lampeyek bi çerxê ve were girêdan derdikeve.', 'Pilin iki elektrodu arasındaki kimyasal tepkime elektronları dış devreye iter ve akım doğar. Isı yalnız küçük bir yan kayıptır; ışık ancak devreye bir lamba bağlanırsa ortaya çıkar.', 2, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=320db6ca49d98b54', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0030
('19e393da-b6ac-542c-a084-94b15393e6e6', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Li gorî qanûna parastina enerjiyê, di pergaleke girtî de enerjî çi dibe?', 'Bi demê re kêm dibe', 'Tenê şeklê xwe diguhere', 'Bi demê re zêde dibe', 'Bi demê re bi tevahî ji holê radibe', 'B', 'Mîqdara giştî wek xwe dimîne; enerjî tenê ji cureyekî derbasî cureyekî din dibe, mînak bo tevgerê an germahiyê. Di lêkxişandinê de enerjî nayê windakirin, bi germahiyeke nizm belav dibe û ji bo kirina karî bêkêr dibe.', 'Mîqdara giştî wek xwe dimîne; enerjî tenê ji cureyekî derbasî cureyekî din dibe, mînak bo tevgerê an germahiyê. Di lêkxişandinê de enerjî nayê windakirin, bi germahiyeke nizm belav dibe û ji bo kirina karî bêkêr dibe.', 'Toplam miktar sabit kalır; enerji yalnız bir türden ötekine geçer, örneğin harekete ya da ısıya. Sürtünmede enerji yok olmaz, düşük sıcaklıkta ısı olarak dağılır ve iş yapmaya elverişsizleşir.', 3, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=d2888122c39924ba', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0031
('8739903f-fc05-5e16-9d24-d51a3f52b1c7', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Çerxeke diranî ya piçûk çerxeke mezin dizivirîne; li ser çerxa mezin çi çêdibe?', 'Hem lez hem tork zêde dibin', 'Hem lez hem tork kêm dibin', 'Lez zêde dibe, tork kêm dibe', 'Lez kêm dibe, tork zêde dibe', 'D', 'Çiqas hejmara diranan zêde bibe, hejmara zivirînên di deqîqeyê de ew qas kêm dibe, lê ji ber ku heman hêz tê veguhastin, moment (gera zivirandinê) mezin dibe. Zêdebûna lez û momentê bi hev re dê bibûya qezenca enerjiyê, ku ev jî ne mimkun e.', 'Çiqas hejmara diranan zêde bibe, hejmara zivirînên di deqîqeyê de ew qas kêm dibe, lê ji ber ku heman hêz tê veguhastin, moment (gera zivirandinê) mezin dibe. Zêdebûna lez û momentê bi hev re dê bibûya qezenca enerjiyê, ku ev jî ne mimkun e.', 'Diş sayısı büyüdükçe dakikadaki tur sayısı düşer, ama aynı güç aktarıldığı için döndürme momenti büyür. Hızın ve torkun birlikte artması güç kazancı demek olurdu, bu da olanaksızdır.', 4, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=8b71884559d131d5', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0032
('e6796c35-556f-5cdf-8209-d4a417fc7b1b', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Cereyana alternatîf ji cereyana rasterast bi kîjan taybetmendiyê cuda dibe?', 'Tenê di têlên ji sifir hatine çêkirin de diherike', 'Voltaja wê her tim sifir e', 'Aliyê wê bi rêkûpêk diguhere', 'Tenê ji pîlan tê wergirtin', 'C', 'Di cereyana alternatîf de voltaj bi dehan caran di saniyeyekê de alî diguherîne, cereyan jî pêş û paş dihejîne; di ya rasterast de alî sabît e. Pîl cereyana rasterast didin, her du celeb jî di heman têlan re derbas dibin.', 'Di cereyana alternatîf de voltaj bi dehan caran di saniyeyekê de alî diguherîne, cereyan jî pêş û paş dihejîne; di ya rasterast de alî sabît e. Pîl cereyana rasterast didin, her du celeb jî di heman têlan re derbas dibin.', 'Alternatif akımda gerilim saniyede onlarca kez işaret değiştirir, bu yüzden akım ileri geri salınır; doğru akımda ise yön sabittir. Piller doğru akım verir ve her iki akım da aynı iletkenlerden geçebilir.', 3, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=ee85ff0923e0dac1', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0033
('e6ee04cb-ceb5-5c33-b868-20676562e622', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Yekîneya pîvana cereyana elektrîkê çi ye?', 'Volt', 'Ohm', 'Wat', 'Amper', 'D', 'Amper, mîqdara barê ku di saniyeyekê de ji rûberekê derbas dibe dipîve. Volt voltajê, ohm berxwedanê, wat jî hêzê nîşan dide; van her sê yekîneyan bi xwe cereyanê nadin.', 'Amper, mîqdara barê ku di saniyeyekê de ji rûberekê derbas dibe dipîve. Volt voltajê, ohm berxwedanê, wat jî hêzê nîşan dide; van her sê yekîneyan bi xwe cereyanê nadin.', 'Amper, saniyede bir kesitten geçen yük miktarını ölçer. Volt gerilimi, ohm direnci, watt ise gücü belirtir; bu üçü akımın kendisini vermez.', 2, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=ef3fb9184725022c', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0034
('e34fc280-102b-5df5-b698-571d17392233', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Çima elektrîk di xetên veguhastinê yên dûr de bi voltajeke pir bilind tê şandin?', 'Ji ber ku têl hingê sivik dibin', 'Ji ber ku windabûna germî kêm dibe', 'Ji bo ku frekans neyê guhertin', 'Ji bo ku amûrên malê zûtir bixebitin', 'B', 'Veguhastina heman hêzê bi voltajeke bilind cereyanê piçûk dike; ji ber ku windahî bi çargoşeya cereyanê zêde dibe, enerjiya wek germahî winda dibe pir kêm dibe. Giraniya kabelê û frekansa torê bi vê hilbijartinê nayên diyarkirin.', 'Veguhastina heman hêzê bi voltajeke bilind cereyanê piçûk dike; ji ber ku windahî bi çargoşeya cereyanê zêde dibe, enerjiya wek germahî winda dibe pir kêm dibe. Giraniya kabelê û frekansa torê bi vê hilbijartinê nayên diyarkirin.', 'Aynı gücü yüksek gerilimle taşımak akımı küçültür; kayıp akımın karesiyle arttığından ısı olarak yitirilen enerji büyük ölçüde düşer. Kablonun ağırlığı ve şebeke frekansı bu seçimle belirlenmez.', 4, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=6461422dc74bdc5e', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0035
('0f93976d-0e73-5d93-b2b9-ac79fa3974f1', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Panela rojê ronahiya rojê rasterast vediguherîne çi?', 'Enerjiya kîmyewî ya hilanîn', 'Enerjiya nukleerî', 'Enerjiya dengî', 'Enerjiya elektrîkî', 'D', 'Di şaneya fotovoltaîk de ronahiya ku tê mijandin elektronan azad dike û rasterast cereyan çêdibe; di navberê de ne jenerator û ne jî turbîn heye. Kolektorên rojê jî elektrîkê çênakin, lê avê germ dikin.', 'Di şaneya fotovoltaîk de ronahiya ku tê mijandin elektronan azad dike û rasterast cereyan çêdibe; di navberê de ne jenerator û ne jî turbîn heye. Kolektorên rojê jî elektrîkê çênakin, lê avê germ dikin.', 'Fotovoltaik hücrede soğurulan ışık elektronları serbest bırakır ve doğrudan akım doğar; arada buhar ya da türbin yoktur. Güneş kolektörleri ise elektrik değil, sıcak su üretir.', 1, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=082cd9ba18177b87', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0036
('82beadc1-690a-58f5-b921-efd66e2b5a9f', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Di sala 1903an de yekem firîna bi motor û bi kontrol kê pêk anî?', 'Birayên Montgolfier', 'Birayên Lumière', 'Birayên Wright', 'Otto Lilienthal', 'C', 'Birayên Wright li Kitty Hawk a li Karolînaya Bakur bi balafira xwe ya motordar firîneke kurt lê bikontrol pêk anîn. Lilienthal bi balafirên bêmotor difiriya, Montgolfier bi balonê firîbûn, Lumière jî bi sînemayê tên naskirin.', 'Birayên Wright li Kitty Hawk a li Karolînaya Bakur bi balafira xwe ya motordar firîneke kurt lê bikontrol pêk anîn. Lilienthal bi balafirên bêmotor difiriya, Montgolfier bi balonê firîbûn, Lumière jî bi sînemayê tên naskirin.', 'Wright kardeşler Kuzey Carolina''daki Kitty Hawk''ta motorlu uçaklarıyla kısa ama yönlendirilebilir bir uçuş yaptı. Lilienthal motorsuz planörlerle süzülmüştü, Montgolfier''ler balonla uçmuştu, Lumière''ler ise sinemayla anılır.', 2, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=2877629f5c8b4544', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0037
('e85224b2-70ca-5d08-a9c6-f9a67418c3b7', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Di 1969an de yekem kesê ku li ser rûyê Heyvê meşiya kî bû?', 'Michael Collins', 'Neil Armstrong', 'Yuri Gagarin', 'Buzz Aldrin', 'B', 'Armstrong, ku fermandarê Apollo 11 bû, çend deqîqe berî Aldrin ji derenceyê daket. Collins li kapsûla sereke di orbîtê de ma; Gagarin di 1961an de yekem mirov bû ku çû fezayê lê neçû Heyvê.', 'Armstrong, ku fermandarê Apollo 11 bû, çend deqîqe berî Aldrin ji derenceyê daket. Collins li kapsûla sereke di orbîtê de ma; Gagarin di 1961an de yekem mirov bû ku çû fezayê lê neçû Heyvê.', 'Apollo 11''in komutanı olan Armstrong, Aldrin''den birkaç dakika önce merdivenden indi. Collins ana kapsülde yörüngede kaldı; Gagarin 1961''de uzaya çıkan ilk insandı ama Ay''a gitmedi.', 1, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=ebfeba2d50835bdf', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0039
('7134ca71-656c-54ed-9333-32adea0a29c6', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Yekem mirovê ku di sala 1961ê de çû fezayê kî bû?', 'Alan Shepard', 'John Glenn', 'Yuri Gagarin', 'Valentina Tereshkova', 'C', 'Gagarin bi kapsûla Vostok 1ê carekê li dora Erdê geriya. Shepard heman salê firîneke gelekî kurttir a bazdanî pêk anî, Glenn di 1962an de çû orbîtê, Tereşkova jî di 1963yan de bû yekem jina ku çû fezayê.', 'Gagarin bi kapsûla Vostok 1ê carekê li dora Erdê geriya. Shepard heman salê firîneke gelekî kurttir a bazdanî pêk anî, Glenn di 1962an de çû orbîtê, Tereşkova jî di 1963yan de bû yekem jina ku çû fezayê.', 'Gagarin, Vostok 1 kapsülüyle Dünya çevresinde bir tur attı. Shepard aynı yıl çok daha kısa bir sıçrama uçuşu yaptı, Glenn 1962''de yörüngeye çıktı, Tereşkova ise 1963''te uzaya giden ilk kadın oldu.', 2, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=035136e9fcf1dbea', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0040
('d6f06e0b-5904-5a94-a664-c82a909454f5', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Roket di valahiya fezayê de çawa pêş de diçe?', 'Bi avêtina gazan ber bi paş', 'Bi palpiştkirina li ser hewayê', 'Bi kişandina qada magnetîk', 'Bi hêza kaşkirina Heyvê', 'A', 'Ji bo her kiryarê bertekek wekhev û berevajî heye: gaza germ a ku ber bi derve ve tê avêtin roketê pêş ve dide, ji ber vê yekê li cihê bêhewa jî dixebite. Eger roket xwe bisparta hewayê, li fezayê qet pêş ve neçûya.', 'Ji bo her kiryarê bertekek wekhev û berevajî heye: gaza germ a ku ber bi derve ve tê avêtin roketê pêş ve dide, ji ber vê yekê li cihê bêhewa jî dixebite. Eger roket xwe bisparta hewayê, li fezayê qet pêş ve neçûya.', 'Her etkiye eşit ve zıt bir tepki vardır: dışarı atılan sıcak gaz roketi ileri iter, bu yüzden hava bulunmayan yerde de çalışır. Havaya yaslanmak gerekseydi uzayda hiç ilerleyemezdi.', 3, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=ac95fefbd6168d2b', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0041
('db35b49e-44ac-5104-96ff-00d4902b2bc3', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Peykên geostasyoner li ser Ekvatorê li derdora kîjan bilindahiyê digerin?', 'Nêzîkî 400 km', 'Nêzîkî 2.000 km', 'Nêzîkî 150.000 km', 'Nêzîkî 36.000 km', 'D', 'Li vê bilindahiyê zivirek tam bîst û çar saetan didome, heke mirov ji erdê lê binêre peyk di ezmên de sabît xuya dike; ji ber vê yekê peykên weşanê li wir tên bicihkirin. 400 km orbîteke nizm e, li wir zivirek nod deqîqeyan dajo.', 'Li vê bilindahiyê zivirek tam bîst û çar saetan didome, heke mirov ji erdê lê binêre peyk di ezmên de sabît xuya dike; ji ber vê yekê peykên weşanê li wir tên bicihkirin. 400 km orbîteke nizm e, li wir zivirek nod deqîqeyan dajo.', 'Bu yükseklikte bir tur tam yirmi dört saat sürer, uydu da yerden bakınca gökyüzünde sabit görünür; yayın uyduları bu yüzden oraya konur. 400 km alçak yörüngedir, orada bir tur doksan dakikadır.', 4, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=72201c8463821289', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0042
('9b194f2d-ba9d-5df2-9fa6-a92d78095e47', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Peykek çima li orbîtê dimîne?', 'Ji ber ku leza wê ya aliyî bi kişandinê re hevseng e', 'Ji ber ku li wê bilindahiyê kişandin tune ye', 'Ji ber ku ji hewayê sivîktir e', 'Ji ber ku motorên wê bi berdewamî û bêrawestan dixebitin', 'A', 'Peyk berdewam dikeve, lê ji ber ku bi lezeke bes zêde jî aliyê din ber bi pêş ve diçe, ji xwarbûna Erdê derbas dibe û naxe wê. Li orbîtê kişandin hê jî bihêz e û peyk sotemeniya xwe ne berdewam dişewitîne.', 'Peyk berdewam dikeve, lê ji ber ku bi lezeke bes zêde jî aliyê din ber bi pêş ve diçe, ji xwarbûna Erdê derbas dibe û naxe wê. Li orbîtê kişandin hê jî bihêz e û peyk sotemeniya xwe ne berdewam dişewitîne.', 'Uydu sürekli düşer, ama aynı anda yeterince hızlı yana gittiği için Dünya''nın eğriliğini ıskalar. Yörüngede yerçekimi hâlâ güçlüdür ve uydular yakıtlarını sürekli yakmaz.', 3, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=454db1cf129bdb53', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0043
('935e48a2-376b-5c52-907b-0be7fde9fd0a', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Hêza hilkişînê ya balafirê bi giranî ji ber çi çêdibe?', 'Ji ber ku balafir ji hewaya derdorê sivîktir e', 'Ji ber germahiya motorê', 'Ji ber cudahiya zextê li ser û bin baskan', 'Ji ber zivirîna Erdê', 'C', 'Hewaya ku li ser baskê re diherike bi lezeke mezintir diherike û li wir zext dadikeve; zexta bilind a li binê baskê wê ber bi jor ve dehf dide. Balon ji ber ku ji hewaya derdora xwe sivîktir in bilind dibin, balafir jî ji hewayê girantir in.', 'Hewaya ku li ser baskê re diherike bi lezeke mezintir diherike û li wir zext dadikeve; zexta bilind a li binê baskê wê ber bi jor ve dehf dide. Balon ji ber ku ji hewaya derdora xwe sivîktir in bilind dibin, balafir jî ji hewayê girantir in.', 'Kanadın üstünden akan hava daha hızlı gider ve orada basınç düşer; alttaki yüksek basınç kanadı yukarı iter. Balonlar çevrelerindeki havadan hafif oldukları için yükselir, uçaklar ise havadan ağırdır.', 3, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=7a5544caa04b84dc', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0044
('3a8b8c73-7aff-591e-8815-2639f487d6b4', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Di sala 1783yan de li Fransayê balona hewaya germ kê firand?', 'Birayên Montgolfier', 'Birayên Wright', 'Ferdinand von Zeppelin', 'Louis Blériot', 'A', 'Balona ji kaxez û qumaş çêbûyî, bi hewaya ku agirê li binê wê germ kiribû bilind bû; yekem firînên bi mirov wiha dest pê kirin. Zeppelin keştiyên hewayî yên bi laşê zexm temsîl dike, Blériot jî derbaskirina Kanala Manşê ya 1909an.', 'Balona ji kaxez û qumaş çêbûyî, bi hewaya ku agirê li binê wê germ kiribû bilind bû; yekem firînên bi mirov wiha dest pê kirin. Zeppelin keştiyên hewayî yên bi laşê zexm temsîl dike, Blériot jî derbaskirina Kanala Manşê ya 1909an.', 'Kâğıt ve kumaştan yapılan balon, altında yakılan ateşin ısıttığı havayla yükseldi; insanlı ilk uçuşlar böyle başladı. Zeppelin sert gövdeli hava gemilerini, Blériot ise 1909''daki Manş geçişini temsil eder.', 3, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=7587becbd6371f81', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0045
('8962fea4-214f-5f40-bdae-d8dc6c675b8e', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Ji bo ku tiştek ji kişandina Erdê bi tevahî xilas bibe, leza wê divê nêzîkî çend be?', '3 km/s', '7,9 km/s', '30 km/s', '11,2 km/s', 'D', 'Leza revê nêzîkî 11,2 km/s ye; 7,9 km/s jî tenê ji bo geriyana li orbîteke nizm têrê dike. 30 km/s leza orbîtê ya Erdê li dora Rojê ye, 3 km/s jî nagihîje tu yekê ji van.', 'Leza revê nêzîkî 11,2 km/s ye; 7,9 km/s jî tenê ji bo geriyana li orbîteke nizm têrê dike. 30 km/s leza orbîtê ya Erdê li dora Rojê ye, 3 km/s jî nagihîje tu yekê ji van.', 'Kaçış hızı yaklaşık 11,2 km/s''dir; 7,9 km/s ise yalnızca alçak yörüngede dolanmaya yeter. 30 km/s Dünya''nın Güneş çevresindeki yörünge hızıdır, 3 km/s ise hiçbirine ulaşmaz.', 4, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=b4006c85dbd0f033', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0046
('cf595e57-d993-5975-b77e-3ee19fefe1eb', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Şopên lingan ên li ser rûyê Heyvê çima demeke pir dirêj dimînin?', 'Ji ber ku ba û baran li wir tune ne', 'Ji ber ku toza wir şil e', 'Ji ber ku germahî pir nizm e', 'Ji ber ku kişandina wê pir bihêz e', 'A', 'Atmosfera Heyvê ya berçav tune ye; ne bayek û ne jî herikîna avê heye ku şopan jê bibe, tenê mîkro-meteorît hêdî hêdî wan xera dikin. Toza Heyvê tam ziwa ye û kişandina wê ji şeşan yekê ya Erdê ye.', 'Atmosfera Heyvê ya berçav tune ye; ne bayek û ne jî herikîna avê heye ku şopan jê bibe, tenê mîkro-meteorît hêdî hêdî wan xera dikin. Toza Heyvê tam ziwa ye û kişandina wê ji şeşan yekê ya Erdê ye.', 'Ay''ın kayda değer bir atmosferi yoktur; izleri silecek rüzgâr ya da su akışı bulunmaz, yalnız mikro göktaşları çok yavaş aşındırır. Ay tozu kupkurudur ve çekimi Dünya''nınkinin altıda biri kadardır.', 3, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=d5c1faabb3332ac2', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0047
('cd1fdf6c-7257-57fc-a5be-cb5a9a75ed53', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Modula heyvî ya Apollo 11ê ku di 1969an de daket bi çi navî hat binavkirin?', 'Columbia', 'Falcon', 'Eagle', 'Challenger', 'C', 'Navê amûra daketinê Eagle bû, navê modula fermandariyê ya ku li orbîtê ma jî Columbia bû. Falcon navê amûra daketinê ya Apollo 15an e, Challenger jî ya Apollo 17an e.', 'Navê amûra daketinê Eagle bû, navê modula fermandariyê ya ku li orbîtê ma jî Columbia bû. Falcon navê amûra daketinê ya Apollo 15an e, Challenger jî ya Apollo 17an e.', 'İniş aracının adı Eagle, yörüngede kalan komuta modülünün adı ise Columbia''ydı. Falcon Apollo 15''in, Challenger Apollo 17''nin iniş araçlarının adıdır.', 5, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=f720f86f3cd39287', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0048
('42877b59-daa0-5118-af64-e79b057b22ef', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Qereqola Fezayê ya Navneteweyî gereke li dora Erdê di çend deqîqeyan de diqedîne?', 'Nêzîkî 12 saet û nîv', 'Nêzîkî 90 deqîqe', 'Nêzîkî 24 saet', 'Nêzîkî 8 deqîqe', 'B', 'Îstasyon li bilindahiyeke nêzî 400 km bi lezeke 28 hezar kîlometreyan di saetê de digere; ev tê wateya ku ji bo ekîbê rojê şazdeh hilatinên rojê hene. Zivireke bîst û çar saetî tenê li orbîta erdmayî ya pir bilindtir çêdibe.', 'Îstasyon li bilindahiyeke nêzî 400 km bi lezeke 28 hezar kîlometreyan di saetê de digere; ev tê wateya ku ji bo ekîbê rojê şazdeh hilatinên rojê hene. Zivireke bîst û çar saetî tenê li orbîta erdmayî ya pir bilindtir çêdibe.', 'İstasyon yaklaşık 400 km yükseklikte saatte 28 bin kilometre hızla dolanır; bu da mürettebat için günde on altı gün doğuşu demektir. Yirmi dört saatlik tur ancak çok daha yüksekteki yer durağan yörüngede olur.', 3, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=008b3bb14fa7cdac', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0050
('241b857c-5518-56e8-a9b4-0c1a02da8f0a', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Sînorê Kármán, ku gelek caran wek destpêka fezayê tê pejirandin, li kîjan bilindahiyê ye?', '100 km', '10 km', '50 km', '500 km', 'A', 'Li nêzî sed kîlometreyan hewa ewqas tenik dibe ku leza pêwîst ji bo çêkirina hêza hilkişînê ya bi baskan nêzîkî leza orbîtê dibe; ji ber vê yekê sînor li wir hatiye danîn. Balafirên rêwiyan li 10-12 km difirin.', 'Li nêzî sed kîlometreyan hewa ewqas tenik dibe ku leza pêwîst ji bo çêkirina hêza hilkişînê ya bi baskan nêzîkî leza orbîtê dibe; ji ber vê yekê sînor li wir hatiye danîn. Balafirên rêwiyan li 10-12 km difirin.', 'Yaklaşık yüz kilometrede hava öyle seyrelir ki kanatla kaldırma üretmek için gereken hız yörünge hızına yaklaşır; sınır bu yüzden oraya konmuştur. Yolcu uçakları 10-12 km''de uçar.', 4, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=dab753b27a6614e3', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0051
('c3384b5a-24bd-5b93-bc7f-613c96ce5c25', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Pergala GPSê cihê amûrekê çawa diyar dike?', 'Bi pîvana hêz û aliyê qada magnetîk a Erdê', 'Bi pîvana dema gihîştina sînyalên peykan', 'Bi wênegirtina ji jor ve', 'Bi bihîstina dengê radyoya herêmî', 'B', 'Wergir, dema ku sînyal ji herî kêm çar peykan digihîje wî dipîve û bi hevgirtina dûrahiyên dîtî cihê hesab dike. Qada magnetîk tenê alî dide, cih nade; peykên GPSê wêne jî nagirin.', 'Wergir, dema ku sînyal ji herî kêm çar peykan digihîje wî dipîve û bi hevgirtina dûrahiyên dîtî cihê hesab dike. Qada magnetîk tenê alî dide, cih nade; peykên GPSê wêne jî nagirin.', 'Alıcı, en az dört uydudan gelen sinyalin yolda geçirdiği süreyi ölçer ve bulduğu uzaklıkları kesiştirerek konumu hesaplar. Manyetik alan yalnız yön verir, konum vermez; GPS uyduları fotoğraf da çekmez.', 3, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=d4d48c17a308a9d2', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0052
('bbce3fbc-299e-5f7c-9d15-4f59667928da', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Du sondeyên Voyager ku di sala 1977an de hatin şandin, wekî armanca sereke ber bi kîjan cismên ezmanî ve çûn?', 'Gerstêrkên dêw ên derve', 'Gerstêrkên bihişk ên hundir', 'Asteroîdên kembera navîn', 'Kometên demdirêj', 'A', 'Voyager 1 û 2 Jupîter û Satirnê lêkolîn kirin; Voyager 2 herwiha çû ba Uranus û Neptunê jî. Rêzkirineke gerstêrkan a kêm-rûdan vê rêyê pêkan kir; gerstêrkên hundir jî bûn karê sondeyên Mariner û Venera.', 'Voyager 1 û 2 Jupîter û Satirnê lêkolîn kirin; Voyager 2 herwiha çû ba Uranus û Neptunê jî. Rêzkirineke gerstêrkan a kêm-rûdan vê rêyê pêkan kir; gerstêrkên hundir jî bûn karê sondeyên Mariner û Venera.', 'Voyager 1 ve 2 Jüpiter ile Satürn''ü inceledi; Voyager 2 ayrıca Uranüs ve Neptün''e uğradı. Gezegenlerin ender bir dizilişi bu rotayı mümkün kıldı, iç gezegenler ise Mariner ve Venera sondalarının işiydi.', 4, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=ae9589b644e723f5', 'approved', 'Kurmancî', 2, now()), -- yerel: tech_invent_0054
('f50eddf5-947d-5e7c-a42c-c0cd898d759b', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Roketên fezayê çima ji çend qonaxan têne çêkirin?', 'Ji bo ku bêtir sotemenî bikişînin', 'Ji bo ku çêkirina wan hêsan bibe', 'Ji bo ku ji dûr ve baştir bên dîtin', 'Ji bo ku giraniya vala bê avêtin', 'D', 'Tank û motorên ku sotemeniya wan xelas bûye dibin giraniyeke mirî; roketa ku wan berdide, bi sotemeniya mayî pir zûtir lezê digire. Avahiya qonaxî hilberînê hêsantir nake, berevajî wê tevlihevtir dike.', 'Tank û motorên ku sotemeniya wan xelas bûye dibin giraniyeke mirî; roketa ku wan berdide, bi sotemeniya mayî pir zûtir lezê digire. Avahiya qonaxî hilberînê hêsantir nake, berevajî wê tevlihevtir dike.', 'Yakıtı biten tank ve motorlar ölü ağırlığa dönüşür; onları bırakan roket kalan yakıtla çok daha fazla hızlanır. Kademeli yapı üretimi kolaylaştırmaz, tersine karmaşıklaştırır.', 3, true, 'multiple_choice', NULL, NULL, 'Dahêner û makîne — zanyariya perwerdehiyê', 'internal:expansion_2026_08/tech_invent#gate=validate_batch.py#hash=7fed47d5604fcd68', 'approved', 'Kurmancî', 2, now()) -- yerel: tech_invent_0055
